<?php
defined('BASEPATH') or exit('No direct script access allowed');

use PhpOffice\PhpSpreadsheet\IOFactory;
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;

class C_rps_generator extends CI_Controller
{
    public function __construct()
    {
        parent::__construct();
        date_default_timezone_set("Asia/Jakarta");

        if (!$this->ion_auth->logged_in()) {
            redirect('auth/login', 'refresh');
        }

        $this->load->model('Setting_api_key_model');
        $this->load->model('Maintenance_model');
        $this->load->library('Ai_reviewer');
        $this->_ensure_kurikulum_schema();

        // Cek mode maintenance untuk Studio RPS
        if ($this->Maintenance_model->is_maintenance('studio_rps') && !$this->Maintenance_model->is_user_exempt()) {
            if ($this->input->is_ajax_request()) {
                $status = $this->Maintenance_model->get_status('studio_rps');
                $this->output->set_content_type('application/json');
                echo json_encode([
                    'status' => 'error',
                    'maintenance' => true,
                    'msg' => $status->message ?? 'Studio RPS OBE sedang dalam pemeliharaan sistem.'
                ]);
                exit;
            } else {
                $status = $this->Maintenance_model->get_status('studio_rps');
                $output['judul_besar'] = 'Pemeliharaan Sistem';
                $output['judul_kecil'] = 'Under Maintenance';
                $output['menu_aktif'] = 'm_rps_generator';
                $output['parent_ws'] = 'active open';
                $output['module_title'] = 'Studio RPS Generator AI';
                $output['maintenance_message'] = $status->message ?? 'Studio RPS Generator sedang dalam pemeliharaan dan peningkatan sistem oleh Administrator Akademik.';
                $output['content'] = 'maintenance/v_maintenance_notice';
                $this->load->view('master_page', $output);
                $this->output->_display();
                exit;
            }
        }
    }

    /**
     * Auto-migrate missing columns in siakad_pustaka_kurikulum if running on fresh DB or another PC/hosting
     */
    private function _ensure_kurikulum_schema()
    {
        if (!$this->db->table_exists('siakad_pustaka_kurikulum')) {
            return;
        }

        $fields = $this->db->list_fields('siakad_pustaka_kurikulum');

        if (!in_array('normalized_json', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `normalized_json` LONGTEXT NULL");
        }
        if (!in_array('normalization_status', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `normalization_status` VARCHAR(50) DEFAULT 'NOT_NORMALIZED'");
        }
        if (!in_array('schema_version', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `schema_version` VARCHAR(20) DEFAULT '1.0'");
        }
        if (!in_array('parser_version', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `parser_version` VARCHAR(50) DEFAULT 'Phase-1.7'");
        }
        if (!in_array('source_hash', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `source_hash` VARCHAR(64) NULL");
        }
        if (!in_array('normalized_at', $fields)) {
            @$this->db->query("ALTER TABLE `siakad_pustaka_kurikulum` ADD COLUMN `normalized_at` DATETIME NULL");
        }
    }

    public function index()
    {
        $id_ptk = $this->session->userdata('id_ptk');
        $api_setting = $this->Setting_api_key_model->get_api_key($id_ptk);

        $provider = $api_setting->ai_provider ?? 'gemini';
        $has_api_key = !empty($api_setting) && !empty($api_setting->api_key);

        // Ambil daftar Program Studi dari tabel sms
        $sms_query = $this->db->select('id_sms, nm_lemb')->from('sms')->order_by('nm_lemb', 'ASC')->get();
        $prodi_list = [];
        if ($sms_query && $sms_query->num_rows() > 0) {
            foreach ($sms_query->result() as $row) {
                if (stripos($row->nm_lemb, 'Politeknik') === false && stripos($row->nm_lemb, 'Direktorat') === false && stripos($row->nm_lemb, 'Bagian') === false) {
                    $prodi_list[$row->nm_lemb] = $row->nm_lemb;
                }
            }
        }
        if (empty($prodi_list)) {
            $prodi_list = [
                'D4 Manajemen Pemasaran Internasional (MPI)' => 'D4 Manajemen Pemasaran Internasional (MPI)',
                'D4 Akuntansi Perpajakan (AP)' => 'D4 Akuntansi Perpajakan (AP)',
                'D4 Agribisnis Hortikultura (AH)' => 'D4 Agribisnis Hortikultura (AH)',
                'D4 Pengelolaan Konvensi dan Acara (PKA)' => 'D4 Pengelolaan Konvensi dan Acara (PKA)',
                'D4 Teknologi Rekayasa Perangkat Lunak (TRPL)' => 'D4 Teknologi Rekayasa Perangkat Lunak (TRPL)'
            ];
        }

        $output['judul_besar'] = 'RPS Generator AI';
        $output['judul_kecil'] = 'OBE & SN-Dikti 2026 (WBI)';
        $output['menu_aktif']  = 'm_rps_generator';
        $output['parent_ws']   = 'active open';
        $output['content']     = 'rps_generator/v_rps_generator';
        $output['after_page']  = 'rps_generator/v_rps_generator_after_page';
        
        $output['ai_provider'] = $provider;
        $output['has_api_key'] = $has_api_key;
        // Ambil nama lengkap dosen dengan gelar dari siakad_dosen (kolom nm_ptk)
        $dosen_row = $this->db->select('nm_ptk')->where('id_ptk', $id_ptk)->get('siakad_dosen')->row();
        $output['user_name'] = ($dosen_row && !empty($dosen_row->nm_ptk)) ? $dosen_row->nm_ptk : ($this->session->userdata('nama') ?: $this->ion_auth->user()->row()->first_name);
        $output['mk_diampu']   = $this->get_daftar_mk_diampu($id_ptk);
        $output['pustaka_list'] = $this->db->order_by('nama_prodi', 'ASC')->get('siakad_pustaka_kurikulum')->result();

        $this->load->view('master_page', $output);
    }

    /**
    /**
     * Helper to determine if a course or schedule is non-classroom (KKN, PKL, MBKM, Tugas Akhir, Skripsi, etc.)
     */
    private function _is_non_classroom_course($name, $code = '')
    {
        $name = trim((string)$name);
        $code = trim((string)$code);

        $excludePatterns = [
            '/\bKKN\b/i',
            '/Kuliah\s*Kerja\s*Nyata/i',
            '/\bPKL\b/i',
            '/Prakte?k\s*Kerja\s*Lapangan/i',
            '/Kerja\s*Prakte?k/i',
            '/\bMagang\b/i',
            '/Internship/i',
            '/\bOJT\b/i',
            '/\bMBKM\b/i',
            '/Merdeka\s*Belajar/i',
            '/Kampus\s*Merdeka/i',
            '/Tugas\s*Akhir/i',
            '/Tugas\s*Karya/i',
            '/Skripsi/i',
            '/Tesis/i',
            '/Seminar\s*Proposal/i',
            '/Sidang/i',
            // MBKM character / soft skills / project activities
            '/^(?:Disiplin|Ekstraksi Ide|Empati|Integritas|Kerangka Pikir|Kerjasama Tim|Pembuatan Purwarupa|Pendampingan Masyarakat|Pengelolaan Pelayanan Sosial|Pengembangan Desain|Penggalian Data|Penyajian Ide|Perumusan Masalah|Perumusan Solusi|Tanggung Jawab|Orientasi pada Target)$/i'
        ];

        foreach ($excludePatterns as $pattern) {
            if (preg_match($pattern, $name)) {
                return true;
            }
        }

        if (!empty($code)) {
            // MBKM activity course codes (e.g. AGH042xx, TRPL042xx, etc.)
            if (preg_match('/^[A-Z]{3,4}04[23]\d{2}$/i', $code)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Helper to get list of distinct courses taught by the lecturer with prodi info
     */
    private function get_daftar_mk_diampu($id_ptk)
    {
        if (empty($id_ptk)) return [];

        $list = [];
        $seen = [];

        // 1. Ambil dari siakad_jadwal (semua semester yang diampu dosen)
        $sql = "SELECT DISTINCT mk.id_mk, mk.kode_mk, mk.nm_mk, mk.sks_mk, kk.sks_mk as sks_kls, s.nm_lemb as nm_prodi, j.tag_name
                FROM siakad_jadwal j
                JOIN siakad_jadwal_detail jd ON jd.id_jadwal = j.id
                JOIN feeder_kelas_kuliah kk ON kk.id_kls = jd.id_kls
                JOIN feeder_mata_kuliah mk ON mk.id_mk = kk.id_mk
                LEFT JOIN sms s ON s.id_sms = COALESCE(kk.id_sms, j.id_sms, mk.id_sms)
                WHERE (j.id_sdm = ? OR j.id_sdm_2 = ? OR j.id_sdm_3 = ?)
                ORDER BY mk.nm_mk ASC";

        $res = $this->db->query($sql, [$id_ptk, $id_ptk, $id_ptk]);
        if ($res && $res->num_rows() > 0) {
            foreach ($res->result() as $row) {
                if ($this->_is_non_classroom_course($row->nm_mk, $row->kode_mk) || $this->_is_non_classroom_course($row->tag_name)) {
                    continue;
                }
                $sks = !empty($row->sks_mk) ? (int)$row->sks_mk : (!empty($row->sks_kls) ? (int)$row->sks_kls : 0);
                $key = strtoupper(trim($row->kode_mk ?: $row->nm_mk)) . '_' . strtoupper(trim($row->nm_prodi ?: ''));
                if (!isset($seen[$key])) {
                    $seen[$key] = true;
                    $list[] = [
                        'id_mk'    => $row->id_mk,
                        'kode_mk'  => $row->kode_mk,
                        'nm_mk'    => $row->nm_mk,
                        'sks'      => $sks,
                        'nm_prodi' => $row->nm_prodi ?: ''
                    ];
                }
            }
        }

        // 2. Fallback jika kosong, ambil dari data RPS yang pernah ada
        if (empty($list)) {
            $rps = $this->db->select('r.id_mk, r.kode_mk, r.nm_mk, s.nm_lemb as nm_prodi')
                ->from('siakad_new_rps_online r')
                ->join('feeder_mata_kuliah mk', 'mk.id_mk = r.id_mk', 'left')
                ->join('sms s', 's.id_sms = mk.id_sms', 'left')
                ->where('r.id_ptk', $id_ptk)
                ->group_by(['r.kode_mk', 'r.nm_mk', 's.nm_lemb'])
                ->get();
            if ($rps && $rps->num_rows() > 0) {
                foreach ($rps->result() as $row) {
                    if ($this->_is_non_classroom_course($row->nm_mk, $row->kode_mk)) {
                        continue;
                    }
                    $key = strtoupper(trim($row->kode_mk ?: $row->nm_mk)) . '_' . strtoupper(trim($row->nm_prodi ?: ''));
                    if (!isset($seen[$key])) {
                        $seen[$key] = true;
                        $list[] = [
                            'id_mk'    => $row->id_mk,
                            'kode_mk'  => $row->kode_mk,
                            'nm_mk'    => $row->nm_mk,
                            'sks'      => 0,
                            'nm_prodi' => $row->nm_prodi ?: ''
                        ];
                    }
                }
            }
        }

        // 3. Fallback jika masih kosong (misal dosen baru), ambil dari kurikulum prodi dosen
        if (empty($list)) {
            $id_sms = $this->session->userdata('prodi');
            if ($id_sms) {
                $mk_prodi = $this->db->select('mk.id_mk, mk.kode_mk, mk.nm_mk, mk.sks_mk, s.nm_lemb as nm_prodi')
                    ->from('feeder_mata_kuliah_kurikulum mkm')
                    ->join('feeder_mata_kuliah mk', 'mk.id_mk = mkm.id_mk')
                    ->join('feeder_kurikulum k', 'k.id_kurikulum_sp = mkm.id_kurikulum_sp')
                    ->join('sms s', 's.id_sms = k.id_sms', 'left')
                    ->where('k.id_sms', $id_sms)
                    ->group_by(['mk.kode_mk', 'mk.nm_mk'])
                    ->order_by('mk.nm_mk', 'ASC')
                    ->limit(60);
                $res_prodi = $mk_prodi->get();
                if ($res_prodi && $res_prodi->num_rows() > 0) {
                    foreach ($res_prodi->result() as $row) {
                        if ($this->_is_non_classroom_course($row->nm_mk, $row->kode_mk)) {
                            continue;
                        }
                        $key = strtoupper(trim($row->kode_mk ?: $row->nm_mk));
                        if (!isset($seen[$key])) {
                            $seen[$key] = true;
                            $list[] = [
                                'id_mk'    => $row->id_mk,
                                'kode_mk'  => $row->kode_mk,
                                'nm_mk'    => $row->nm_mk,
                                'sks'      => (int)$row->sks_mk,
                                'nm_prodi' => $row->nm_prodi ?: ''
                            ];
                        }
                    }
                }
            }
        }

        return $list;
    }

    /**
     * AJAX: Search mata kuliah server-side for Select2 (minimum 3 characters)
     */
    public function ajax_search_mata_kuliah()
    {
        $this->output->set_content_type('application/json');

        $searchTerm = trim($this->input->get_post('q') ?: $this->input->get_post('term') ?: '');
        if (mb_strlen($searchTerm) < 3) {
            echo json_encode(['results' => []]);
            return;
        }

        $id_ptk = $this->session->userdata('id_ptk') ?: ($this->ion_auth->user()->row() ? $this->ion_auth->user()->row()->id_ptk : '');
        $termLike = '%' . $searchTerm . '%';

        // 1. Query gabungan feeder_mata_kuliah + prodi (sms) + penanda diampu oleh dosen login
        $sql = "SELECT DISTINCT 
                    mk.id_mk, 
                    mk.kode_mk, 
                    mk.nm_mk, 
                    mk.sks_mk, 
                    COALESCE(NULLIF(s.nm_lemb, ''), (SELECT s2.nm_lemb FROM feeder_kelas_kuliah kk JOIN sms s2 ON s2.id_sms = kk.id_sms WHERE kk.id_mk = mk.id_mk LIMIT 1), '') as nm_prodi,
                    (SELECT COUNT(*) FROM siakad_jadwal j 
                     JOIN siakad_jadwal_detail jd ON jd.id_jadwal = j.id 
                     JOIN feeder_kelas_kuliah kk ON kk.id_kls = jd.id_kls 
                     WHERE kk.id_mk = mk.id_mk AND (j.id_sdm = ? OR j.id_sdm_2 = ? OR j.id_sdm_3 = ?)) as diampu_saya
                FROM feeder_mata_kuliah mk
                LEFT JOIN sms s ON s.id_sms = mk.id_sms
                WHERE (mk.kode_mk LIKE ? OR mk.nm_mk LIKE ?)
                ORDER BY diampu_saya DESC, mk.nm_mk ASC
                LIMIT 40";

        $res = $this->db->query($sql, [$id_ptk, $id_ptk, $id_ptk, $termLike, $termLike]);
        $results = [];
        $seen = [];

        if ($res && $res->num_rows() > 0) {
            foreach ($res->result() as $row) {
                if ($this->_is_non_classroom_course($row->nm_mk, $row->kode_mk)) {
                    continue;
                }

                $sks = (int)$row->sks_mk;
                $prodi = trim($row->nm_prodi ?: '');
                $key = strtoupper(trim($row->kode_mk ?: $row->nm_mk)) . '_' . strtoupper($prodi);

                if (!isset($seen[$key])) {
                    $seen[$key] = true;
                    $isDiampu = ((int)$row->diampu_saya > 0);
                    $textDisplay = '[' . ($row->kode_mk ?: '-') . '] ' . $row->nm_mk . ($sks > 0 ? " ({$sks} SKS)" : '') . ($prodi ? " — {$prodi}" : '') . ($isDiampu ? ' (Diampu)' : '');

                    $uniqueSelectId = $row->id_mk ?: ($row->kode_mk ? ($row->kode_mk . '___' . $row->nm_mk) : $row->nm_mk);

                    $results[] = [
                        'id'       => $uniqueSelectId,
                        'text'     => $textDisplay,
                        'id_mk'    => $row->id_mk,
                        'kode_mk'  => $row->kode_mk ?: '',
                        'nm_mk'    => $row->nm_mk,
                        'sks'      => $sks,
                        'nm_prodi' => $prodi,
                        'diampu'   => $isDiampu
                    ];
                }
            }
        }

        echo json_encode(['results' => $results]);
    }

    /**
     * AJAX: Parse uploaded reference file (PDF, DOCX, TXT) to text
     */
    public function ajax_upload_doc()
    {
        $this->output->set_content_type('application/json');

        if (empty($_FILES['doc_file']['name'])) {
            echo json_encode(['status' => false, 'msg' => 'Tidak ada file yang diunggah.']);
            return;
        }

        $file_name = $_FILES['doc_file']['name'];
        $file_tmp  = $_FILES['doc_file']['tmp_name'];
        $file_ext  = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));

        $allowed_exts = ['pdf', 'docx', 'txt', 'rtf', 'md'];
        if (!in_array($file_ext, $allowed_exts)) {
            echo json_encode(['status' => false, 'msg' => 'Format file tidak didukung. Harap unggah file PDF, DOCX, TXT, atau MD.']);
            return;
        }

        $extracted_text = '';

        try {
            if ($file_ext === 'pdf') {
                $parser = new \Smalot\PdfParser\Parser();
                $pdf    = $parser->parseFile($file_tmp);
                $extracted_text = $pdf->getText();
            } elseif ($file_ext === 'docx') {
                $extracted_text = $this->extract_docx_text($file_tmp);
            } else {
                $extracted_text = file_get_contents($file_tmp);
            }
        } catch (Exception $e) {
            echo json_encode(['status' => false, 'msg' => 'Gagal membaca dokumen: ' . $e->getMessage()]);
            return;
        }

        $extracted_text = trim($extracted_text);
        if (empty($extracted_text)) {
            echo json_encode([
                'status' => false,
                'msg'    => 'Dokumen kosong atau teks tidak terbaca (jika PDF, pastikan bukan hasil scan tanpa OCR).'
            ]);
            return;
        }

        // Jika yang diunggah adalah Kurikulum & CPL, otomatis simpan/perbarui ke Pustaka Kurikulum
        $doc_type = $this->input->post('doc_type', true);
        $pustaka_info = null;

        if ($doc_type === 'kurikulum') {
            $nama_prodi = trim($this->input->post('nama_prodi', true));
            if (empty($nama_prodi)) {
                $nama_prodi = 'Umum / WBI';
            }

            $upload_dir = FCPATH . 'uploads/pustaka_kurikulum/';
            if (!is_dir($upload_dir)) {
                @mkdir($upload_dir, 0777, true);
            }

            $safe_slug = preg_replace('/[^a-zA-Z0-9_-]/', '_', $nama_prodi);
            $ts = time();
            $orig_saved_name = 'doc_' . $safe_slug . '_' . $ts . '.' . $file_ext;
            $text_saved_name = 'content_' . $safe_slug . '_' . $ts . '.md';

            @copy($file_tmp, $upload_dir . $orig_saved_name);
            @file_put_contents($upload_dir . $text_saved_name, $extracted_text);

            $id_ptk = $this->session->userdata('id_ptk');
            $user_name = $this->session->userdata('nama') ?: ($this->ion_auth->user()->row()->first_name ?? 'Dosen');

            $data_pustaka = [
                'nama_prodi'        => $nama_prodi,
                'judul_dokumen'     => 'Kurikulum & CPL ' . $nama_prodi,
                'file_name'         => $file_name,
                'file_path_doc'     => 'uploads/pustaka_kurikulum/' . $orig_saved_name,
                'file_path_content' => 'uploads/pustaka_kurikulum/' . $text_saved_name,
                'total_karakter'    => strlen($extracted_text),
                'uploaded_by_ptk'   => $id_ptk,
                'uploaded_by_nama'  => $user_name,
                'updated_at'        => date('Y-m-d H:i:s')
            ];

            $exist = $this->db->where('nama_prodi', $nama_prodi)->get('siakad_pustaka_kurikulum')->row();
            if ($exist) {
                $this->db->where('id', $exist->id)->update('siakad_pustaka_kurikulum', $data_pustaka);
                $pustaka_id = $exist->id;
            } else {
                $data_pustaka['created_at'] = date('Y-m-d H:i:s');
                $this->db->insert('siakad_pustaka_kurikulum', $data_pustaka);
                $pustaka_id = $this->db->insert_id();
            }

            $pustaka_info = [
                'id'               => $pustaka_id,
                'nama_prodi'       => $nama_prodi,
                'file_name'        => $file_name,
                'total_karakter'   => strlen($extracted_text),
                'uploaded_by_nama' => $user_name,
                'updated_at'       => date('d M Y, H:i')
            ];
        }

        echo json_encode([
            'status'       => true,
            'file_name'    => $file_name,
            'char_count'   => strlen($extracted_text),
            'text'         => $extracted_text,
            'pustaka_info' => $pustaka_info
        ]);
    }

    /**
     * Download Template Resmi WBI: Rincian 16 Pertemuan (13 Kolom)
     */
    public function download_template_16_pertemuan()
    {
        $template_path = APPPATH . 'libraries/ai_skills/akademik-dosen-obe-fiq/templates/template_rps_wbi_rincian_pertemuan.xlsx';
        if (!file_exists($template_path)) {
            $template_path = APPPATH . 'third_party/rps_obe/template_rps_wbi_rincian_pertemuan.xlsx';
        }
        if (!file_exists($template_path)) {
            show_error('File template 16 pertemuan tidak ditemukan di server: ' . $template_path);
            return;
        }

        $filename = 'Template_RPS_WBI_16_Pertemuan_13_Kolom.xlsx';
        header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        header('Content-Disposition: attachment;filename="' . $filename . '"');
        header('Cache-Control: max-age=0');
        readfile($template_path);
        exit;
    }

    /**
     * AJAX: Parse & Validasi File Spreadsheet Excel 16 Pertemuan (13 Kolom)
     */
    public function ajax_upload_excel_pertemuan()
    {
        $this->output->set_content_type('application/json');

        if (empty($_FILES['excel_file']['name'])) {
            echo json_encode(['status' => false, 'msg' => 'Tidak ada file Excel yang diunggah.']);
            return;
        }

        $file_name = $_FILES['excel_file']['name'];
        $file_tmp  = $_FILES['excel_file']['tmp_name'];
        $file_ext  = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));

        if (!in_array($file_ext, ['xlsx', 'xls'])) {
            echo json_encode(['status' => false, 'msg' => 'Format file tidak didukung. Harap unggah file spreadsheet Excel (.xlsx atau .xls).']);
            return;
        }

        try {
            $spreadsheet = IOFactory::load($file_tmp);
            $sheet       = $spreadsheet->getActiveSheet();
            $highestRow  = (int)$sheet->getHighestRow();

            $clean_str = function($val) {
                if ($val === null || $val === '') return '';
                $val = (string)$val;
                $val = str_replace(["\r\n", "\r"], "\n", $val);
                return trim($val);
            };

            // Deteksi baris mulai data (Default template baris 6 s.d. 21)
            $start_row = 6;
            $header_cell = strtolower(trim((string)$sheet->getCell('A1')->getValue()));
            if ($header_cell !== 'kolom_1' && !str_contains($header_cell, 'minggu')) {
                // Cari baris data pertama secara dinamis jika bukan dari template baku
                for ($r = 1; $r <= min(15, $highestRow); $r++) {
                    $valA = trim((string)$sheet->getCell('A' . $r)->getValue());
                    $valB = trim((string)$sheet->getCell('B' . $r)->getValue());
                    $valC = trim((string)$sheet->getCell('C' . $r)->getValue());
                    if ((is_numeric($valA) || is_numeric($valB)) && !empty($valC) && !in_array(strtolower($valC), ['kemampuan akhir tiap tahapan belajar', 'kemampuan akhir', 'sub-cpmk', 'sub cpmk'])) {
                        $start_row = $r;
                        break;
                    }
                }
            }

            $parsed_rows = [];
            $total_meetings_target = 16;
            $row_idx = 0;

            for ($row_num = $start_row; $row_num <= $highestRow; $row_num++) {
                if ($row_idx >= $total_meetings_target) break;

                $col_a = $clean_str($sheet->getCell('A' . $row_num)->getValue());
                $col_b = $clean_str($sheet->getCell('B' . $row_num)->getValue());
                $col_c = $clean_str($sheet->getCell('C' . $row_num)->getValue());
                $col_d = $clean_str($sheet->getCell('D' . $row_num)->getValue());
                $col_e = $clean_str($sheet->getCell('E' . $row_num)->getValue());
                $col_f = $clean_str($sheet->getCell('F' . $row_num)->getValue());
                $col_g = $clean_str($sheet->getCell('G' . $row_num)->getValue());
                $col_h = $sheet->getCell('H' . $row_num)->getValue();
                $col_i = $sheet->getCell('I' . $row_num)->getValue();
                $col_j = $clean_str($sheet->getCell('J' . $row_num)->getValue());
                $col_k = $clean_str($sheet->getCell('K' . $row_num)->getValue());
                $col_l = $sheet->getCell('L' . $row_num)->getValue();
                $col_m = $clean_str($sheet->getCell('M' . $row_num)->getValue());

                // Skip baris jika kolom penting kosong semua
                if (empty($col_c) && empty($col_d) && empty($col_e) && empty($col_a) && empty($col_b)) {
                    continue;
                }

                $row_idx++;
                $minggu_no = is_numeric($col_a) ? (int)$col_a : $row_idx;
                $pertemuan_no = is_numeric($col_b) ? (int)$col_b : $row_idx;

                // Bobot parsing (hilangkan % atau konversi pecahan desimal misal 0.05 -> 5)
                $bobot_val = 0;
                if ($col_l !== null && $col_l !== '') {
                    $raw_bobot = str_replace('%', '', (string)$col_l);
                    if (is_numeric($raw_bobot)) {
                        $f_bobot = (float)$raw_bobot;
                        $bobot_val = ($f_bobot > 0 && $f_bobot < 1) ? (int)round($f_bobot * 100) : (int)round($f_bobot);
                    }
                }

                $waktu_t_val = is_numeric($col_h) ? (int)$col_h : 50;
                $waktu_p_val = is_numeric($col_i) ? (int)$col_i : 100;

                $parsed_rows[] = [
                    'minggu'              => $minggu_no,
                    'pertemuan'           => $pertemuan_no,
                    'sub_cpmk'            => $col_c ?: ('Sub-CPMK Pertemuan ' . $pertemuan_no),
                    'bahan_kajian'        => $col_d ?: '-',
                    'bentuk_pembelajaran' => $col_e ?: 'Kuliah (Tatap Muka / Daring)',
                    'metode'              => $col_f ?: 'Ceramah interaktif, Diskusi Kelompok',
                    'pengalaman_belajar'  => $col_g ?: 'Menganalisis konsep materi dan menyelesaikan studi kasus',
                    'waktu_teori'         => $waktu_t_val,
                    'waktu_praktek'       => $waktu_p_val,
                    'kriteria_evaluasi'   => $col_j ?: 'Rubrik Penilaian Partisipasi & Tugas',
                    'indikator_evaluasi'  => $col_k ?: 'Ketepatan analisis dan penguasaan konsep materi',
                    'bobot'               => $bobot_val,
                    'sumber_belajar'      => $col_m ?: '-'
                ];
            }

            if (empty($parsed_rows)) {
                echo json_encode([
                    'status' => false,
                    'msg'    => 'Tidak dapat menemukan baris data pertemuan pada file Excel. Pastikan file menggunakan format template 13 kolom yang sesuai.'
                ]);
                return;
            }

            // Bangun Markdown Table Bagian 6 untuk naskah RPS
            $md_table = "## 6. DETAIL RENCANA PEMBELAJARAN MINGGUAN (TABEL 16 PERTEMUAN)\n";
            $md_table .= "| Minggu | Kemampuan Akhir Tiap Tahapan Belajar | Bahan Kajian | Bentuk dan Modalitas Pembelajaran | Metode Pembelajaran | Pengalaman Belajar | Waktu (T/P) | Kriteria Evaluasi | Indikator Evaluasi | Bobot (%) | Sumber Belajar |\n";
            $md_table .= "|---|---|---|---|---|---|---|---|---|---|---|\n";

            $summary_lines = [];
            foreach ($parsed_rows as $pr) {
                $sub_clean   = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['sub_cpmk']);
                $bk_clean    = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['bahan_kajian']);
                $bentuk_cl   = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['bentuk_pembelajaran']);
                $metode_cl   = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['metode']);
                $peng_cl     = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['pengalaman_belajar']);
                $waktu_str   = $pr['waktu_teori'] . '/' . $pr['waktu_praktek'];
                $krit_cl     = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['kriteria_evaluasi']);
                $ind_cl      = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['indikator_evaluasi']);
                $bobot_str   = $pr['bobot'] . '%';
                $sumber_cl   = str_replace(["\r\n", "\n", "\r", "|"], [' ', ' ', ' ', ' '], $pr['sumber_belajar']);

                $md_table .= "| " . $pr['minggu'] . " | " . $sub_clean . " | " . $bk_clean . " | " . $bentuk_cl . " | " . $metode_cl . " | " . $peng_cl . " | " . $waktu_str . " | " . $krit_cl . " | " . $ind_cl . " | " . $bobot_str . " | " . $sumber_cl . " |\n";

                $summary_lines[] = "- Pertemuan {$pr['pertemuan']} (Minggu {$pr['minggu']}): {$sub_clean} | Bahan Kajian: {$bk_clean} | Bobot: {$bobot_str}";
            }

            $summary_text = implode("\n", $summary_lines);

            echo json_encode([
                'status'          => true,
                'file_name'       => $file_name,
                'total_pertemuan' => count($parsed_rows),
                'matrix_data'     => $parsed_rows,
                'markdown_table'  => $md_table,
                'summary_text'    => $summary_text,
                'msg'             => 'Berhasil memproses ' . count($parsed_rows) . ' pertemuan dari file Excel ' . htmlspecialchars($file_name) . '.'
            ]);

        } catch (Exception $e) {
            echo json_encode([
                'status' => false,
                'msg'    => 'Gagal membaca file Excel: ' . $e->getMessage()
            ]);
        }
    }

    /**
     * Helper to compute SHA-256 source hash from content
     */
    private function _calculate_source_hash($content)
    {
        return hash('sha256', (string)$content);
    }

    /**
     * Helper to validate Structured Curriculum Library payload (Schema v1.0)
     */
    private function _clean_curriculum_pdf_pollution($text)
    {
        $text = preg_replace('/POLITEKNIK\s*WBI\s*\d{4}/i', '', (string)$text);
        $text = preg_replace('/\d+\s*\|\s*P\s*a\s*g\s*e/i', '', $text);
        $text = preg_replace('/\d+\s*\|\s*Page/i', '', $text);
        $text = preg_replace('/Aspek\s+Kode\s+Diskripsi\s+Capaian\s+Pembelajaran\s+Lulusan/i', '', $text);
        return trim($text);
    }

    private function _normalize_course_string_key($str)
    {
        return strtolower(preg_replace('/[^a-z0-9]/i', '', (string)$str));
    }

    private function _validate_structured_curriculum_completeness($payload)
    {
        $errors = [];
        $cpl_count = isset($payload['official_cpl']) && is_array($payload['official_cpl']) ? count($payload['official_cpl']) : 0;
        $mk_count  = isset($payload['mata_kuliah']) && is_array($payload['mata_kuliah']) ? count($payload['mata_kuliah']) : 0;

        if ($cpl_count === 0) {
            $errors[] = 'Completeness Error: official_cpl_count must be greater than 0.';
        }
        if ($mk_count === 0) {
            $errors[] = 'Completeness Error: mata_kuliah_count is 0 but curriculum document contains course distribution section.';
        }

        // Referential integrity check
        $all_mk = $payload['mata_kuliah'] ?? [];
        $direct_pairs = $payload['direct_cpl_mk_pairs'] ?? [];
        $bk_pairs = $payload['bk_mk_pairs'] ?? [];

        // Aggregate tracks lookup (e.g. INTERNSHIP_TRACK, TATA_NILAI)
        $aggregate_track_lookup = [];
        if (!empty($payload['matrix_reconciliation']['aggregate_tracks']) && is_array($payload['matrix_reconciliation']['aggregate_tracks'])) {
            foreach ($payload['matrix_reconciliation']['aggregate_tracks'] as $at) {
                if (!empty($at['aggregate_code'])) {
                    $aggregate_track_lookup[$this->_normalize_course_string_key($at['aggregate_code'])] = true;
                }
                if (!empty($at['matrix_column'])) {
                    $aggregate_track_lookup[$this->_normalize_course_string_key($at['matrix_column'])] = true;
                }
            }
        }
        $aggregate_track_lookup['internshiptrack'] = true;
        $aggregate_track_lookup['internship'] = true;
        $aggregate_track_lookup['tatanilai'] = true;

        if (!empty($direct_pairs) && $mk_count === 0) {
            $errors[] = 'Referential Integrity Error: direct_cpl_mk_pairs exist but mata_kuliah_count is 0.';
        }

        foreach ($direct_pairs as $dp) {
            $p_code = $this->_normalize_course_string_key($dp['mk_code'] ?? '');
            $p_name = $this->_normalize_course_string_key($dp['mk_name'] ?? '');
            $is_aggregate = (!empty($dp['mapping_scope']) && $dp['mapping_scope'] === 'TRACK_AGGREGATE')
                || isset($aggregate_track_lookup[$p_code])
                || isset($aggregate_track_lookup[$p_name]);
            
            if ($is_aggregate) {
                continue;
            }

            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($p_code) && $p_code === $m_code) || (!empty($p_name) && (str_contains($m_name, $p_name) || str_contains($p_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: direct_cpl_mk_pair pointing to unresolvable MK [{$dp['mk_code']}] {$dp['mk_name']}.";
            }
        }

        foreach ($bk_pairs as $bp) {
            $b_code = $this->_normalize_course_string_key($bp['mk_code'] ?? '');
            $b_name = $this->_normalize_course_string_key($bp['mk_name'] ?? '');
            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($b_code) && $b_code === $m_code) || (!empty($b_name) && (str_contains($m_name, $b_name) || str_contains($b_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: bk_mk_pair pointing to unresolvable MK [{$bp['mk_code']}] {$bp['mk_name']}.";
            }
        }

        // Effective CPL-MK pairs validation
        $effective_pairs = $payload['effective_cpl_mk_pairs'] ?? [];
        $cpls = $payload['official_cpl'] ?? [];
        $cpl_lookup = [];
        foreach ($cpls as $c) {
            $code = $c['code'] ?? '';
            if (empty($code)) continue;
            $cpl_lookup[$code] = true;
            $unhyphenated = str_replace('-', '', $code);
            $cpl_lookup[$unhyphenated] = true;
            if (str_starts_with($code, 'KU-')) {
                $cpl_lookup[str_replace('KU-', 'U-', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'U', $code)] = true;
            } elseif (str_starts_with($code, 'U-')) {
                $cpl_lookup[str_replace('U-', 'KU-', $code)] = true;
                $cpl_lookup[str_replace('U-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('U-', 'U', $code)] = true;
            }
            if (str_starts_with($code, 'KK-')) {
                $cpl_lookup[str_replace('KK-', 'KS-', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KS', $code)] = true;
            } elseif (str_starts_with($code, 'KS-')) {
                $cpl_lookup[str_replace('KS-', 'KK-', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KS', $code)] = true;
            }
        }
        $bk_lookup = [];
        foreach (($payload['bahan_kajian'] ?? []) as $b) {
            $bk_lookup[$b['code']] = true;
        }

        foreach ($effective_pairs as $ep) {
            $ep_cpl = $ep['cpl_code'] ?? '';
            $ep_mk_code = $this->_normalize_course_string_key($ep['mk_code'] ?? '');
            $ep_mk_name = $this->_normalize_course_string_key($ep['mk_name'] ?? '');
            $ep_mtype = $ep['mapping_type'] ?? '';
            $ep_bk = $ep['bk_code'] ?? '';

            if (!isset($cpl_lookup[$ep_cpl])) {
                $errors[] = "Referential Integrity Error: effective_cpl_mk_pair uses invalid cpl_code '{$ep_cpl}'.";
            }
            if ($ep_mtype === 'DERIVED_VIA_BK' && !isset($bk_lookup[$ep_bk])) {
                $errors[] = "Referential Integrity Error: derived effective pair uses unresolvable bk_code '{$ep_bk}'.";
            }

            $is_aggregate = (!empty($ep['mapping_scope']) && $ep['mapping_scope'] === 'TRACK_AGGREGATE')
                || isset($aggregate_track_lookup[$ep_mk_code])
                || isset($aggregate_track_lookup[$ep_mk_name]);
            if ($is_aggregate) {
                continue;
            }

            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($ep_mk_code) && $ep_mk_code === $m_code) || (!empty($ep_mk_name) && (str_contains($m_name, $ep_mk_name) || str_contains($ep_mk_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: effective_cpl_mk_pair pointing to unresolvable MK [{$ep['mk_code']}] {$ep['mk_name']}.";
            }
        }

        // Aggregate Domain Mappings validation (e.g. TATA_NILAI)
        $agg_mappings = $payload['aggregate_domain_mappings'] ?? [];
        foreach ($agg_mappings as $am) {
            $a_code = $this->_normalize_course_string_key($am['mk_code'] ?? '');
            $a_name = $this->_normalize_course_string_key($am['mk_name'] ?? '');
            $is_aggregate = (!empty($am['mapping_scope']) && $am['mapping_scope'] === 'TRACK_AGGREGATE')
                || isset($aggregate_track_lookup[$a_code])
                || isset($aggregate_track_lookup[$a_name]);
            if ($is_aggregate) {
                continue;
            }

            $resolved = false;
            foreach ($all_mk as $m) {
                $m_code = $this->_normalize_course_string_key($m['kode_mk'] ?? '');
                $m_name = $this->_normalize_course_string_key($m['nama_mk'] ?? '');
                if ((!empty($a_code) && $a_code === $m_code) || (!empty($a_name) && (str_contains($m_name, $a_name) || str_contains($a_name, $m_name)))) {
                    $resolved = true;
                    break;
                }
            }
            if (!$resolved) {
                $errors[] = "Referential Integrity Error: aggregate_domain_mapping pointing to unresolvable MK [{$am['mk_code']}] {$am['mk_name']}.";
            }
        }

        return [
            'valid'  => empty($errors),
            'errors' => $errors
        ];
    }

    private function _validate_structured_curriculum_library($payload)
    {
        $errors = [];
        if (!is_array($payload)) {
            return ['valid' => false, 'errors' => ['Payload is not a valid JSON object/array.']];
        }

        // Schema version
        if (empty($payload['schema_version'])) {
            $errors[] = 'Missing schema_version.';
        }

        // Prodi
        if (empty($payload['prodi']['nama_resmi'])) {
            $errors[] = 'Missing prodi.nama_resmi.';
        }

        // Official CPL validation
        if (!isset($payload['official_cpl']) || !is_array($payload['official_cpl']) || empty($payload['official_cpl'])) {
            $errors[] = 'official_cpl must be a non-empty array.';
        } else {
            $seen_codes = [];
            foreach ($payload['official_cpl'] as $idx => $cpl) {
                $code = $cpl['code'] ?? '';
                if (empty($code)) {
                    $errors[] = "official_cpl[{$idx}] missing code.";
                } elseif (isset($seen_codes[$code])) {
                    $errors[] = "Duplicate official_cpl code: {$code}.";
                }
                $seen_codes[$code] = true;

                if (empty($cpl['category']) || !in_array($cpl['category'], ['S', 'P', 'KU', 'KK', 'U', 'K', 'SIKAP', 'PENGETAHUAN', 'KETERAMPILAN KHUSUS', 'KETERAMPILAN UMUM', 'CPL', 'OTHER'])) {
                    $errors[] = "official_cpl[{$idx}] code {$code} has invalid category: " . ($cpl['category'] ?? 'empty');
                }
                if (empty($cpl['description'])) {
                    $errors[] = "official_cpl[{$idx}] code {$code} has empty description.";
                }
            }
        }

        // CPL-BK mapping validation
        if (isset($payload['cpl_bk_mapping'])) {
            $status = $payload['cpl_bk_mapping']['status'] ?? '';
            if (!in_array($status, ['PARSED', 'AVAILABLE_UNPARSED', 'NOT_AVAILABLE'])) {
                $errors[] = "Invalid cpl_bk_mapping status: {$status}.";
            }
            if ($status === 'PARSED' && (!is_array($payload['cpl_bk_mapping']['pairs'] ?? null) || ($payload['cpl_bk_mapping']['mappable_count'] ?? null) === null)) {
                $errors[] = "cpl_bk_mapping status PARSED requires mappable_count integer and pairs array.";
            }
        }

        if (isset($payload['cpl_mk_mapping_audit'])) {
            $audit = $payload['cpl_mk_mapping_audit'];
            $m_status = $audit['mapping_parse_status'] ?? '';
            if (!in_array($m_status, ['SOURCE_MAPPING_PARSED', 'SOURCE_MAPPING_PARTIAL', 'SOURCE_MAPPING_AVAILABLE_UNPARSED', 'SOURCE_MAPPING_PARSER_ERROR', 'SOURCE_MAPPING_NOT_AVAILABLE'])) {
                $errors[] = "Status mapping_parse_status pada cpl_mk_mapping_audit tidak valid: {$m_status}.";
            }
        }

        // Run completeness and referential integrity rules
        $completeness = $this->_validate_structured_curriculum_completeness($payload);
        if (!$completeness['valid']) {
            $errors = array_merge($errors, $completeness['errors']);
        }

        $bk_completeness = $this->_validate_bahan_kajian_completeness($payload);
        if (!$bk_completeness['valid']) {
            $errors = array_merge($errors, $bk_completeness['errors']);
        }

        return [
            'valid'  => empty($errors),
            'errors' => $errors
        ];
    }

    private function _validate_bahan_kajian_completeness($payload)
    {
        $errors = [];
        $bks = $payload['bahan_kajian'] ?? [];
        $prodi = $payload['prodi']['nama_resmi'] ?? '';

        if (empty($bks) || !is_array($bks)) {
            $errors[] = 'Completeness Error: bahan_kajian array cannot be empty.';
            return ['valid' => false, 'errors' => $errors];
        }

        $seen = [];
        foreach ($bks as $idx => $b) {
            $code = $b['code'] ?? '';
            $name = $b['name'] ?? '';
            $source_name = $b['source_name'] ?? '';

            if (empty($code)) {
                $errors[] = "Bahan Kajian pada indeks {$idx} tidak memiliki kode.";
            } elseif (isset($seen[$code])) {
                $errors[] = "Duplikasi kode Bahan Kajian: {$code}.";
            }
            $seen[$code] = true;

            if (empty($name)) {
                $errors[] = "Bahan Kajian {$code} memiliki nama kosong.";
            }
            if (empty($source_name)) {
                if (!empty($name)) {
                    $b['source_name'] = $name;
                } else {
                    $errors[] = "Bahan Kajian {$code} memiliki source_name kosong (Source Fidelity Error).";
                }
            }

            // Pollution check
            if (preg_match('/^(?:Landasan|Visi|Misi|Tujuan\s*Program|Bab\b|Matriks\b|Struktur\s*Mata|Distribusi\s*Mata)/i', $name)) {
                $errors[] = "Pollution terdeteksi pada Bahan Kajian {$code}: '{$name}'.";
            }
        }

        // Expected count validation per prodi
        $count = count($bks);
        if (stripos($prodi, 'Agribisnis') !== false && $count !== 20) {
            $errors[] = "Agribisnis Hortikultura harus memiliki tepat 20 Bahan Kajian (ditemukan {$count}).";
        } elseif (stripos($prodi, 'Perangkat Lunak') !== false && $count !== 11) {
            $errors[] = "Teknologi Rekayasa Perangkat Lunak harus memiliki tepat 11 Bahan Kajian (ditemukan {$count}).";
        } elseif (stripos($prodi, 'Akuntansi') !== false && $count !== 13) {
            $errors[] = "Akuntansi Perpajakan harus memiliki tepat 13 Bahan Kajian (ditemukan {$count}).";
        } elseif (stripos($prodi, 'Konvensi') !== false && $count !== 32) {
            $errors[] = "Pengelolaan Konvensi dan Acara harus memiliki tepat 32 Bahan Kajian (ditemukan {$count}).";
        } elseif ((stripos($prodi, 'Pemasaran') !== false || stripos($prodi, 'Perusahaan') !== false) && $count !== 10) {
            $errors[] = "Manajemen Pemasaran Internasional harus memiliki tepat 10 Bahan Kajian (ditemukan {$count}).";
        }

        // Referential integrity check for BK-MK pairs
        $all_mk = $payload['mata_kuliah'] ?? [];
        $bk_mk_pairs = $payload['bk_mk_pairs'] ?? [];
        foreach ($bk_mk_pairs as $pair) {
            $bkc = $pair['bk_code'] ?? '';
            if (!isset($seen[$bkc])) {
                $errors[] = "Referential Integrity Error: bk_mk_pair menggunakan bk_code tidak valid '{$bkc}'.";
            }
        }

        // Referential integrity check for CPL-BK pairs
        $cpl_bk_pairs = $payload['cpl_bk_mapping']['pairs'] ?? [];
        $cpls = $payload['official_cpl'] ?? [];
        $cpl_lookup = [];
        foreach ($cpls as $c) {
            $code = $c['code'] ?? '';
            if (empty($code)) continue;
            $cpl_lookup[$code] = true;
            $unhyphenated = str_replace('-', '', $code);
            $cpl_lookup[$unhyphenated] = true;
            if (str_starts_with($code, 'KU-')) {
                $cpl_lookup[str_replace('KU-', 'U-', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('KU-', 'U', $code)] = true;
            } elseif (str_starts_with($code, 'U-')) {
                $cpl_lookup[str_replace('U-', 'KU-', $code)] = true;
                $cpl_lookup[str_replace('U-', 'KU', $code)] = true;
                $cpl_lookup[str_replace('U-', 'U', $code)] = true;
            }
            if (str_starts_with($code, 'KK-')) {
                $cpl_lookup[str_replace('KK-', 'KS-', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KK-', 'KS', $code)] = true;
            } elseif (str_starts_with($code, 'KS-')) {
                $cpl_lookup[str_replace('KS-', 'KK-', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KK', $code)] = true;
                $cpl_lookup[str_replace('KS-', 'KS', $code)] = true;
            }
        }

        foreach ($cpl_bk_pairs as $pair) {
            $bkc = $pair['bk_code'] ?? '';
            $cpc = $pair['cpl_code'] ?? '';
            if (!isset($seen[$bkc])) {
                $errors[] = "Referential Integrity Error: cpl_bk_pair menggunakan bk_code tidak valid '{$bkc}'.";
            }
            if (!isset($cpl_lookup[$cpc])) {
                $errors[] = "Referential Integrity Error: cpl_bk_pair menggunakan cpl_code tidak valid '{$cpc}'.";
            }
        }

        return [
            'valid'  => empty($errors),
            'errors' => $errors
        ];
    }

