            ['cpl_code' => 'P-5', 'bk_code' => '3.5', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
            ['cpl_code' => 'P-5', 'bk_code' => '3.6', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
            ['cpl_code' => 'P-5', 'bk_code' => '3.7', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
            ['cpl_code' => 'P-5', 'bk_code' => '3.8', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
            ['cpl_code' => 'P-6', 'bk_code' => '5.1', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
            ['cpl_code' => 'P-6', 'bk_code' => '5.2', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
            ['cpl_code' => 'P-6', 'bk_code' => '5.3', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
            ['cpl_code' => 'P-6', 'bk_code' => '5.4', 'mapping_type' => 'EXPLICIT_MATRIX', 'source_section' => 'Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran', 'source_page' => 15, 'evidence' => 'Tanda centang pada matriks resmi Matriks I. Hubungan Bahan Kajian dan Capaian Pembelajaran'],
