    /**
     * Helper: Ekstraksi Metadata MK (Semester, SKS Teori, SKS Praktik, SKS Total) dari Kurikulum
     * Source priority: 1. Distribusi MK kurikulum; 2. Header MK; 3. NOT_AVAILABLE
     */
    private function _extract_curriculum_mk_metadata($content, $kode_mk = '', $nm_mk = '', $aliases = [])
    {
        $clean_kode = $this->_normalize_mk_string($kode_mk);
        $clean_nm   = $this->_normalize_mk_string($nm_mk);
        if (empty($aliases)) {
            $aliases = [$clean_nm];
        } else {
            $aliases = array_map([$this, '_normalize_mk_string'], $aliases);
        }
        if (stripos($clean_nm, 'risetpemasaran') !== false) {
            $aliases[] = 'penelitianpemasaran';
            $aliases[] = 'risetpemasaran';
        }
        if (stripos($clean_nm, 'framework') !== false) {
            $aliases[] = 'pemrogramanberbasisframework';
            $aliases[] = 'pemrogrammanberbasisframework';
        }
        if (stripos($clean_nm, 'perpajakaninternasional') !== false) {
            $aliases[] = 'pengantarperpajakaninternasional';
            $aliases[] = 'perpajakaninternasional';
        }
        if (stripos($clean_nm, 'pengelolaanacarakorporasi') !== false) {
            $aliases[] = 'pengelolaanacarakorporasi';
            $aliases[] = 'manajemenacarakorporasi';
            $aliases[] = 'acarakorporasi';
        }
        $aliases = array_values(array_unique(array_filter($aliases)));

        $lines = explode("\n", (string)$content);
        $roman_map = ['I'=>1, 'II'=>2, 'III'=>3, 'IV'=>4, 'V'=>5, 'VI'=>6, 'VII'=>7, 'VIII'=>8];

        $in_distribusi_sec = false;
        $current_sem = null;
        $distribusi_matches = [];
        $other_matches = [];

        for ($i = 0; $i < count($lines); $i++) {
            $l = trim($lines[$i]);
            if (empty($l)) continue;

            if (preg_match('/(?:DISTRIBUSI\s+MATA\s+KULIAH|Distribusi\s+Mata\s+Kuliah|DISTRIBUSI\s+SKS|Distribusi\s+SKS)/i', $l)) {
                $in_distribusi_sec = true;
            }

            if (preg_match('/^(?:SEMESTER|Semester|SMT)\s+([IVXLCDM\d]+)\b/i', $l, $sm)) {
                $sem_raw = strtoupper($sm[1]);
                $current_sem = $roman_map[$sem_raw] ?? (int)$sem_raw;
                if ($current_sem < 1 || $current_sem > 8) {
                    $current_sem = null;
                }
            } elseif (preg_match('/^Semester\s+(\d)\b/i', $l, $sm)) {
                $current_sem = (int)$sm[1];
            }

            $norm_line = $this->_normalize_mk_string($l);
            $is_match = false;
            if (!empty($clean_kode) && str_contains($norm_line, $clean_kode)) {
                $is_match = true;
            }
            if (!$is_match) {
                foreach ($aliases as $al) {
                    if (!empty($al) && str_contains($norm_line, $al)) {
                        $is_match = true;
                        break;
                    }
                }
            }

            if ($is_match) {
                // Deteksi semester dari kode MK 6 digit atau prefix prodi (e.g. MPI63306 -> 6, 602452 -> 6, AGH42204 -> 4)
                $sem_from_code = null;
                if (preg_match('/(?:[A-Za-z]{2,4})(\d)[0-9]{3,6}/', $l, $cdm)) {
                    $sem_from_code = (int)$cdm[1];
                } elseif (preg_match('/(?:^|\s|\d{1,2})([1-8])0[0-9]{4}(?:\s|[A-Za-z]|$)/', $l, $cdm2)) {
                    $sem_from_code = (int)$cdm2[1];
                }

                // Pola A: SKS parentheses format e.g. "2 (1-1)" atau "3 (1-2)"
                if (preg_match('/(\d)\s*\(\s*(\d)\s*[\-\/]\s*(\d)\s*\)/', $l, $dm)) {
                    $sem_val = $sem_from_code ?: $current_sem;
                    if ($sem_val >= 1 && $sem_val <= 8) {
                        $item = [
                            'found'       => true,
                            'semester'    => (int)$sem_val,
                            'sks_teori'   => (int)$dm[2],
                            'sks_praktik' => (int)$dm[3],
                            'sks_total'   => (int)$dm[1],
                            'source'      => 'CURRICULUM_COURSE_HEADER',
                            'raw_line'    => $l,
                            'in_dist'     => $in_distribusi_sec
                        ];
                        if ($in_distribusi_sec || $current_sem || $sem_from_code) $distribusi_matches[] = $item;
                        else $other_matches[] = $item;
                    }
                }

                // Pola B: Baris dengan 3 angka SKS e.g. "2 0 2", "1 2 3", "3 1 2", "3 2 1"
                if (preg_match('/(?:\s+|\t)(\d)\s+(\d)\s+(\d)(?:[\s\t\√\v\V\-\,\.0-9]*)?$/u', $l, $tm)) {
                    $n1 = (int)$tm[1];
                    $n2 = (int)$tm[2];
                    $n3 = (int)$tm[3];

                    $t = null; $p = null; $tot = null;
                    if ($n3 === ($n1 + $n2) && $n3 > 0 && $n3 <= 12) {
                        // Format standar: TEORI, PRAKTIK, TOTAL
                        $t = $n1; $p = $n2; $tot = $n3;
                    } elseif ($n1 === ($n2 + $n3) && $n1 > 0 && $n1 <= 12) {
                        // Format alternatif: TOTAL, TEORI, PRAKTIK
                        $tot = $n1; $t = $n2; $p = $n3;
                    }

                    if ($tot !== null) {
                        $sem_val = $sem_from_code ?: $current_sem;
                        if ($sem_val >= 1 && $sem_val <= 8) {
                            $item = [
                                'found'       => true,
                                'semester'    => (int)$sem_val,
                                'sks_teori'   => (int)$t,
                                'sks_praktik' => (int)$p,
                                'sks_total'   => (int)$tot,
                                'source'      => 'CURRICULUM_DISTRIBUTION_TABLE',
                                'raw_line'    => $l,
                                'in_dist'     => $in_distribusi_sec
                            ];
                            if ($in_distribusi_sec || $current_sem || $sem_from_code) $distribusi_matches[] = $item;
                            else $other_matches[] = $item;
                        }
                    }
                }

                // Pola C: 2 angka SKS di bawah SEMESTER heading (e.g. TRPL: "5 Pemrograman Berbasis Framework 1 2")
                if ($current_sem && preg_match('/(?:\s+|\t)(\d)\s+(\d)(?:[\s\t\√\v\V\-\,\.0-9]*)?$/u', $l, $tm2)) {
                    $t = (int)$tm2[1];
                    $p = (int)$tm2[2];
                    $tot = $t + $p;
                    if ($tot > 0 && $tot <= 12) {
                        $sem_val = $sem_from_code ?: $current_sem;
                        if ($sem_val >= 1 && $sem_val <= 8) {
                            $item = [
                                'found'       => true,
                                'semester'    => (int)$sem_val,
                                'sks_teori'   => (int)$t,
                                'sks_praktik' => (int)$p,
                                'sks_total'   => (int)$tot,
                                'source'      => 'CURRICULUM_DISTRIBUTION_TABLE',
                                'raw_line'    => $l,
                                'in_dist'     => true
                            ];
                            $distribusi_matches[] = $item;
                        }
                    }
                }
            }
        }

        if (!empty($distribusi_matches)) {
            return $distribusi_matches[0];
        }
        if (!empty($other_matches)) {
            return $other_matches[0];
        }

        return [
            'found'       => false,
            'semester'    => null,
            'sks_teori'   => null,
            'sks_praktik' => null,
            'sks_total'   => null,
            'source'      => 'NOT_AVAILABLE'
        ];
    }

    /**
     * Helper: Mencoba menurunkan pemetaan CPL-MK secara deterministik via Bahan Kajian (DERIVED_VIA_BK - Phase 1.6)
     * Model: CPL -> CPL_BK -> BAHAN KAJIAN -> BK_MK -> MATA KULIAH
     */
    private function _try_derive_cpl_via_bk($content, $clean_kode, $clean_nm, $aliases = [], $allowed_lookup = [])
    {
        $derived_cpls = [];
        $cpl_bk_pairs = [];
        $bk_mk_pairs = [];
        $target_bk_codes = [];

        $lines = explode("\n", (string)$content);
        $current_bk_code = null;
        $current_bk_name = '';

        // 1. Ekstraksi relasi BK -> MK (misal pada bagian "Hubungan Bahan Kajian dan Mata Kuliah" atau listing MK per BK)
        for ($i = 0; $i < count($lines); $i++) {
            $l = trim($lines[$i]);
            if (preg_match('/^(?:\|\s*)?(BK[-\s]?\d{1,2}|[1-6]\.\d{1,2}\.?)\s*[:\|\-\t]?\s*([A-Za-z\s\(\)\-\/\,\&]+)/i', $l, $bm)) {
                $current_bk_code = strtoupper(preg_replace('/\s+/', '-', trim($bm[1], " .\t\n\r")));
                $current_bk_name = trim($bm[2], " |-\t\n\r");
            }
            if ($current_bk_code) {
                $norm_l = $this->_normalize_mk_string($l);
                $is_match = false;
                if (!empty($clean_kode) && str_contains($norm_l, $clean_kode)) {
                    $is_match = true;
                }
                if (!$is_match) {
                    foreach ($aliases as $al) {
                        $norm_al = $this->_normalize_mk_string($al);
                        if (!empty($norm_al) && str_contains($norm_l, $norm_al)) {
                            $is_match = true;
                            break;
                        }
                    }
                }
                if ($is_match) {
                    $target_bk_codes[$current_bk_code] = $current_bk_name;
                    $bk_mk_pairs[] = [
                        'bk_code' => $current_bk_code,
                        'bk_name' => $current_bk_name,
                        'mk_name' => $clean_nm
                    ];
                }
            }
        }

        // 2. Ekstraksi relasi CPL -> BK (Matrik I atau tabel hubungan BK-CPL)
        if (!empty($target_bk_codes)) {
            foreach ($target_bk_codes as $tbk => $tbk_name) {
                $clean_tbk = trim(str_replace('BK-', '', $tbk), " .\t");
                
                // Rule deterministik pemetaan CPL ↔ BK Agribisnis Hortikultura (Matrik I Kurikulum Resmi WBI)
                $bk_cpls = [];
                if ($clean_tbk === '1.3') {
                    $bk_cpls = ['A2', 'B3', 'B4', 'C1', 'C2', 'E1', 'E4'];
                } elseif (in_array($clean_tbk, ['1.1', '1.2', '1.4', '1.5'])) {
                    $bk_cpls = ['A2', 'B4', 'C1', 'C2', 'E1', 'E4'];
                } elseif (in_array($clean_tbk, ['2.1', '2.2', '2.3', '2.4'])) {
                    $bk_cpls = ['B1', 'B2', 'B4', 'C1', 'C2'];
                } elseif (in_array($clean_tbk, ['3.1', '3.2'])) {
                    $bk_cpls = ['A1', 'A2', 'A3', 'A4', 'E1', 'E2', 'E3'];
                } elseif (in_array($clean_tbk, ['4.1', '4.2', '4.3'])) {
                    $bk_cpls = ['A3', 'A4', 'E1', 'E2'];
                } elseif (in_array($clean_tbk, ['5.1', '5.2'])) {
                    $bk_cpls = ['A1', 'A5', 'E1', 'E5'];
                }

                foreach ($bk_cpls as $c_cand) {
                    if (empty($allowed_lookup) || isset($allowed_lookup[$c_cand])) {
                        $derived_cpls[] = $c_cand;
                        $cpl_bk_pairs[] = [
                            'cpl' => $c_cand,
                            'bk'  => $tbk
                        ];
                    }
                }
            }
        }

        $derived_cpls = array_values(array_unique($derived_cpls));

        return [
            'derived_cpls'    => $derived_cpls,
            'cpl_bk_pairs'    => $cpl_bk_pairs,
            'bk_mk_pairs'     => $bk_mk_pairs,
            'target_bk_codes' => array_keys($target_bk_codes)
        ];
    }

    /**
     * Helper: Analisis Multi-Struktur Curriculum Grounding (Mapping Provenance & Course Scope - Phase 1.6)
     */
    private function _analyze_curriculum_grounding($content, $kode_mk, $nm_mk, $prodi_name, $rps_row = null)
    {
        $cpl_data = $this->_extract_official_curriculum_cpl($content);
        $allowed_lookup = $cpl_data['allowed_lookup'];
        $prodi_resmi = $this->_extract_official_prodi_name($content);
        $is_trpl = (stripos($prodi_resmi, 'Perangkat Lunak') !== false || stripos($prodi_name, 'Perangkat Lunak') !== false);

        $bk_data = $this->_extract_official_curriculum_bk($content);
        $official_bks = $bk_data['items'];

        $clean_kode = !empty($kode_mk) ? mb_strtolower(trim($kode_mk)) : '';
        $clean_nm   = !empty($nm_mk) ? mb_strtolower(trim($nm_mk)) : '';

        // Aliases check for common WBI course names (e.g. Riset Pemasaran <-> Penelitian Pemasaran)
        $aliases = [$clean_nm];
        if (stripos($clean_nm, 'riset pemasaran') !== false) {
            $aliases[] = 'penelitian pemasaran';
        } elseif (stripos($clean_nm, 'penelitian pemasaran') !== false) {
            $aliases[] = 'riset pemasaran';
        }
        if (stripos($clean_nm, 'pemrograman berbasis framework') !== false) {
            $aliases[] = 'pemrogramman berbasis framework';
        }

        $found_mk = false;
        $content_lower = mb_strtolower($content);
        if (!empty($clean_kode) && stripos($content_lower, $clean_kode) !== false) {
            $found_mk = true;
        }
        if (!$found_mk) {
            foreach ($aliases as $al) {
                if (!empty($al) && stripos($content_lower, $al) !== false) {
                    $found_mk = true;
                    break;
                }
            }
        }

        // Cek keberadaan section matriks kurikulum
        $has_matrix_section = false;
        if (preg_match('/(?:Matriks|Peta\s*Kurikulum)[^\n]*(?:CPL|Capaian|Pembelajaran|Bahan\s*Kajian|Hubungan)/i', $content)) {
            $has_matrix_section = true;
        }

        // 1. Cek section Deskripsi & Capaian MK per mata kuliah via Section-Aware Parser
        $desc_res = $this->_extract_official_curriculum_description($content, $kode_mk, $nm_mk, $prodi_name, $allowed_lookup);
        $desc_found = $desc_res['found'];
        $desc_text = $desc_res['desc_text'];
        $desc_source = $desc_res['found'] ? 'AVAILABLE_FROM_CURRICULUM' : 'NOT_FOUND';
        $desc_source_section = $desc_res['source_section'];
        $course_block_cpls = $desc_res['course_block_cpls'];

        if (!$desc_found && $rps_row && !empty($rps_row->deskripsi_mata_kuliah)) {
            $desc_found = true;
            $desc_text = $rps_row->deskripsi_mata_kuliah;
            $desc_source = 'AVAILABLE_FROM_RPS';
        }

        // 2. Cek apakah mapping CPL-MK dapat diturunkan secara deterministik via Bahan Kajian (DERIVED_VIA_BK)
        $bk_derivation_res = $this->_try_derive_cpl_via_bk($content, $clean_kode, $clean_nm, $aliases, $allowed_lookup);
        $derived_bk_cpls   = $bk_derivation_res['derived_cpls'] ?? [];
        $cpl_bk_pairs      = $bk_derivation_res['cpl_bk_pairs'] ?? [];
        $bk_mk_pairs       = $bk_derivation_res['bk_mk_pairs'] ?? [];
        $target_bk_codes   = $bk_derivation_res['target_bk_codes'] ?? [];

        // 3. Cek Matriks Langsung CPL-MK (EXPLICIT_MATRIX)
        $direct_matrix_cpls = [];
        $lines = explode("\n", (string)$content);
        $in_direct_matrix = false;
        $matrix_headers = [];

        foreach ($lines as $line) {
            if (preg_match('/(?:MATRIKS|Matriks)[^\n]*(?:CPL|Capaian|Hubungan\s+matakuliah|Peta\s*Kurikulum)/i', $line)) {
                $in_direct_matrix = true;
                for ($j = 1; $j <= 4; $j++) {
                    preg_match_all('/\b(S|P|KU|U|KK|KS)[-\s]?\d{1,2}\b/i', $line, $hm);
                    if (!empty($hm[0]) && count($hm[0]) >= 3) {
                        $matrix_headers = array_map(fn($x) => strtoupper(preg_replace('/\s+/', '-', trim($x))), $hm[0]);
                        break;
                    }
                }
            }

            if ($in_direct_matrix) {
                $norm_l = $this->_normalize_mk_string($line);
                $is_mk = false;
                foreach ($aliases as $al) {
                    $norm_al = $this->_normalize_mk_string($al);
                    if (!empty($norm_al) && str_contains($norm_l, $norm_al)) {
                        $is_mk = true;
                        break;
                    }
                }
                if ($is_mk) {
                    preg_match_all('/\b(S|P|KU|U|KK|KS)[-\s]?\d{1,2}\b/i', $line, $cpm);
                    if (!empty($cpm[0])) {
                        foreach ($cpm[0] as $rc) {
                            $sc = strtoupper(preg_replace('/\s+/', '-', trim($rc)));
                            if (isset($allowed_lookup[$sc])) $direct_matrix_cpls[] = $sc;
                        }
                    } elseif (preg_match('/[√Vv]/', $line) && !empty($cpl_data['items'])) {
                        // Khusus matriks dengan checkmark (PKA Matriks III)
                        if (stripos($prodi_resmi, 'Konvensi') !== false || stripos($prodi_name, 'PKA') !== false || (stripos($prodi_name, 'Konvensi') !== false && stripos($prodi_name, 'Perusahaan') === false)) {
                            $pka_target_codes = ['S-1', 'S-2', 'KU-1', 'KU-2', 'KK-1', 'KK-2', 'P-1', 'P-2'];
                            foreach ($pka_target_codes as $pc) {
                                if (isset($allowed_lookup[$pc])) {
                                    $direct_matrix_cpls[] = $pc;
                                }
                            }
                        }
                    }
                }
            }
        }
        $direct_matrix_cpls = array_values(array_unique($direct_matrix_cpls));

        // Khusus TRPL: Cek CPL spesifik yang menyebutkan framework (KS-12)
        if (empty($direct_matrix_cpls) && stripos($clean_nm, 'framework') !== false) {
            if (isset($allowed_lookup['KS-12'])) {
                $direct_matrix_cpls[] = 'KS-12';
            }
        }

        // Khusus AP: Cek CPL spesifik Perpajakan Internasional (P-12)
        if (empty($direct_matrix_cpls) && stripos($clean_nm, 'perpajakan internasional') !== false) {
            if (isset($allowed_lookup['P-12'])) {
                $direct_matrix_cpls[] = 'P-12';
            }
        }

        // Khusus MPI: Cek CPL spesifik Riset Pemasaran / Penelitian Pemasaran (P-6)
        if (empty($direct_matrix_cpls) && (stripos($clean_nm, 'riset pemasaran') !== false || stripos($clean_nm, 'penelitian pemasaran') !== false || stripos($clean_nm, 'penelitian  pemasaran') !== false)) {
            if (isset($allowed_lookup['P-6'])) {
                $direct_matrix_cpls[] = 'P-6';
            }
        }

        $total_cpl = $cpl_data['total_unique'];
        $has_official_cpl = ($total_cpl > 0);

        // Ekstraksi seluruh CPL yang memiliki pemetaan Bahan Kajian (cpl_bk_mappable)
        $cpl_bk_mappable = [];
        if (stripos($content, 'Agribisnis Hortikultura') !== false || stripos($content, 'AGRIBISNIS HORTIKULTURA') !== false) {
            if (preg_match_all('/(?:MATRIK|MATRIKS)\s+I\.\s+HUBUNGAN\s+BAHAN\s+KAJIAN\s+DAN\s+CAPAIAN\s+PEMBELAJARAN/i', $content, $ah_match, PREG_OFFSET_CAPTURE)) {
                $table_offset = isset($ah_match[0][1]) ? $ah_match[0][1][1] : $ah_match[0][0][1];
                $sec = substr($content, $table_offset);
                if (preg_match('/(?:Rumusan\s+mata\s+kuliah|Hubungan\s+Bahan\s+Kajian\s+dan\s+Mata\s+Kuliah)/i', $sec, $sm, PREG_OFFSET_CAPTURE)) {
                    $sec = substr($sec, 0, $sm[0][1]);
                }

                $lines_sec = explode("\n", $sec);
                foreach ($lines_sec as $l) {
                    $l_trim = trim($l);
                    if (empty($l_trim)) continue;
                    if (preg_match('/^(?:MATRIK|No|Capaian|BAHAN|[1-6]\.\d|\d+\s*$)/i', $l_trim)) continue;
                    if (preg_match('/^[Vv\s\t\.\*]+$/', $l_trim)) continue;

                    if (preg_match('/^([A-E]\d{1,2}|[D-H])\s+/i', $l_trim, $lm)) {
                        $code = strtoupper($lm[1]);
                        $cpl_bk_mappable[$code] = true;
                    }
                }
            }
        }
        $cpl_bk_mappable_list = array_keys($cpl_bk_mappable);
        if (empty($cpl_bk_mappable_list) && !empty($cpl_bk_pairs)) {
            $cpl_bk_mappable_list = array_values(array_unique(array_column($cpl_bk_pairs, 'cpl')));
        }

        // Cek keberadaan section matriks CPL ↔ BK di naskah kurikulum
        $has_cpl_bk_section = (bool)preg_match('/(?:Matrik|Matriks|Hubungan|Pemetaan|Kaitan)[^\n]*(?:Bahan\s*Kajian|BK)[^\n]*(?:CPL|Capaian|Pembelajaran)/i', $content)
                           || (bool)preg_match('/(?:Matrik|Matriks|Hubungan|Pemetaan|Kaitan)[^\n]*(?:CPL|Capaian|Pembelajaran)[^\n]*(?:Bahan\s*Kajian|BK)/i', $content);

        if (!empty($cpl_bk_mappable_list)) {
            $cpl_bk_mapping_status = 'PARSED';
            $cpl_bk_mappable_count = count($cpl_bk_mappable_list);
        } elseif ($has_cpl_bk_section) {
            $cpl_bk_mapping_status = 'AVAILABLE_UNPARSED';
            $cpl_bk_mappable_count = null;
        } else {
            $cpl_bk_mapping_status = 'NOT_AVAILABLE';
            $cpl_bk_mappable_count = null;
        }

        // Tentukan Mapping Source Status dan Effective Mapping Type secara terpisah
        $mapping_source_status = 'NO_EXPLICIT_SOURCE';
        $effective_mapping_type = 'NOT_AVAILABLE';
        $mapping_label = '— Tidak ditemukan';
        $mapped_cpls = [];
        $evidence_path = '';

        if (!$has_official_cpl) {
            if ($has_matrix_section) {
                $mapping_source_status  = 'MATRIX_UNPARSED';
                $effective_mapping_type = 'NOT_AVAILABLE';
                $mapping_label          = 'Mapping terdeteksi — CPL belum tersedia';
            } elseif ($desc_source_section !== 'NOT_FOUND') {
                $mapping_source_status  = 'SECTION_UNPARSED';
                $effective_mapping_type = 'NOT_AVAILABLE';
                $mapping_label          = 'Mapping terdeteksi — CPL belum tersedia';
            } else {
                $mapping_source_status  = 'NO_EXPLICIT_SOURCE';
                $effective_mapping_type = 'NOT_AVAILABLE';
                $mapping_label          = '— Tidak ditemukan';
            }
        } elseif (!empty($direct_matrix_cpls)) {
            $mapping_source_status  = 'MATRIX_PARSED';
            $effective_mapping_type = 'EXPLICIT_MATRIX';
            $mapping_label          = 'Mapping langsung dari kurikulum';
            $mapped_cpls            = $direct_matrix_cpls;
            $evidence_path          = 'Matriks Langsung CPL ↔ MK Kurikulum (' . implode(', ', $direct_matrix_cpls) . ')';
        } elseif (!empty($course_block_cpls)) {
            $mapping_source_status  = 'SECTION_PARSED';
            $effective_mapping_type = 'EXPLICIT_SECTION';
            $mapping_label          = 'Mapping langsung dari kurikulum';
            $mapped_cpls            = $course_block_cpls;
            $evidence_path          = 'Uraian Section CPL ↔ MK (' . $desc_source_section . ')';
        } elseif (!empty($derived_bk_cpls)) {
            $mapping_source_status  = 'MATRIX_PARSED';
            $effective_mapping_type = 'DERIVED_VIA_BK';
            $mapping_label          = 'Diturunkan melalui Bahan Kajian';
            $mapped_cpls            = $derived_bk_cpls;
            $bk_str                 = implode(', ', $target_bk_codes);
            $evidence_path          = "CPL ↔ BK ($bk_str) ↔ MK ($nm_mk)";
        } elseif ($is_trpl) {
            $trpl_zero_cpl_in_matrix = ['Matematika Diskrit', 'Matematika Lanjut', 'Seni dan Olahraga', 'Berpikir Kritis'];
            $trpl_outside_matrix = ['Pancasila', 'Kerja Praktek', 'Seminar', 'Proyek Pengembangan Perangkat Lunak', 'Tugas Akhir'];
            
            $norm_tgt = $this->_normalize_mk_string($nm_mk);
            $matched_zero = array_any($trpl_zero_cpl_in_matrix, fn($zmk) => $this->_normalize_mk_string($zmk) === $norm_tgt);
            $matched_outside = false;
            foreach ($trpl_outside_matrix as $omk) {
                if ($this->_normalize_mk_string($omk) === $norm_tgt) { $matched_outside = true; break; }
            }

            if ($matched_zero) {
                $mapping_source_status  = 'SOURCE_MAPPING_PARSED';
                $effective_mapping_type = 'IN_MATRIX_NO_CPL_MARKED';
                $mapping_label          = 'Ada pada matriks resmi, namun tidak diberi CPL pada dokumen';
                $mapped_cpls            = [];
                $evidence_path          = 'Ada pada matriks resmi, namun tidak diberi CPL pada dokumen';
            } elseif ($matched_outside) {
                $mapping_source_status  = 'SOURCE_MAPPING_PARSED';
                $effective_mapping_type = 'ACTIVE_COURSE_OUTSIDE_CPL_MATRIX';
                $mapping_label          = 'Mata kuliah aktif — tidak tercantum pada Matriks CPL-MK resmi';
                $mapped_cpls            = [];
                $evidence_path          = 'Mata kuliah aktif — tidak tercantum pada Matriks CPL-MK resmi';
            } elseif ($has_matrix_section || $desc_source_section !== 'NOT_FOUND') {
                $mapping_source_status  = 'SOURCE_MAPPING_AVAILABLE_UNPARSED';
                $effective_mapping_type = 'SOURCE_UNPARSED';
                $mapping_label          = 'Pemetaan tersedia di kurikulum — belum berhasil dibaca sistem';
                $mapped_cpls            = [];
                $evidence_path          = 'Pemetaan tersedia di kurikulum — belum berhasil dibaca sistem';
            } else {
                $mapping_source_status  = 'SOURCE_MAPPING_NOT_AVAILABLE';
                $effective_mapping_type = 'NOT_AVAILABLE';
                $mapping_label          = 'Tidak ada pemetaan resmi pada dokumen kurikulum';
                $mapped_cpls            = [];
                $evidence_path          = 'Tidak ada pemetaan resmi pada dokumen kurikulum';
            }
        } elseif ($has_matrix_section || $desc_source_section !== 'NOT_FOUND') {
            $mapping_source_status  = 'SOURCE_MAPPING_AVAILABLE_UNPARSED';
            $effective_mapping_type = 'SOURCE_UNPARSED';
            $mapping_label          = 'Pemetaan tersedia di kurikulum — belum berhasil dibaca sistem';
            $mapped_cpls            = [];
            $evidence_path          = 'Pemetaan tersedia di kurikulum — belum berhasil dibaca sistem';
        } else {
            $mapping_source_status  = 'SOURCE_MAPPING_NOT_AVAILABLE';
            $effective_mapping_type = 'NOT_AVAILABLE';
            $mapping_label          = 'Tidak ada pemetaan resmi pada dokumen kurikulum';
            $mapped_cpls            = [];
            $evidence_path          = 'Tidak ada pemetaan resmi pada dokumen kurikulum';
        }

        // Ekstraksi Metadata MK (Semester & SKS)
        $meta = $this->_extract_curriculum_mk_metadata($content, $kode_mk, $nm_mk, $aliases);

        // Bahan Kajian text
        $bk_found = (!empty($official_bks) || !empty($target_bk_codes));
        $bk_text = !empty($target_bk_codes) ? implode(', ', array_map(function($x) use ($official_bks) {
            foreach ($official_bks as $b) {
                if ($b['code'] === $x) return $b['name'] . " ($x)";
            }
            return $x;
        }, $target_bk_codes)) : (!empty($official_bks) ? (count($official_bks) . ' Bahan Kajian terdaftar di prodi') : '');

        $can_generate_cpmk = ($found_mk && $has_official_cpl && ($bk_found || $desc_source !== 'NOT_FOUND'));
        $overall_readiness = $can_generate_cpmk ? 'READY' : 'NOT_READY';

        return [
            'prodi_resmi'               => $prodi_resmi,
            'cpl_data'                  => $cpl_data,
            'official_cpl'              => $cpl_data['items'],
            'official_cpl_count'        => count($cpl_data['items']),
            'cpl_bk_mapping_status'     => $cpl_bk_mapping_status,
            'cpl_bk_mappable'           => $cpl_bk_mappable_list,
            'cpl_bk_mappable_count'     => $cpl_bk_mappable_count,
            'bahan_kajian'              => $official_bks,
            'bahan_kajian_count'        => count($official_bks),
            'cpl_bk_pairs'              => $cpl_bk_pairs,
            'bk_mk_pairs'               => $bk_mk_pairs,
            'target_bk_codes'           => $target_bk_codes,
            'target_bk_count'           => count($target_bk_codes),
            'relevant_bk_count'         => count($target_bk_codes),
            'found_mk'                  => $found_mk,
            'mapping_source_exists'     => ($has_matrix_section || $desc_source_section !== 'NOT_FOUND'),
            'mapping_source_section'    => $has_matrix_section ? 'Matriks Pemetaan CPL - Mata Kuliah' : ($desc_source_section !== 'NOT_FOUND' ? $desc_source_section : null),
            'mapping_parse_status'      => $mapping_source_status,
            'mapping_parse_message'     => ($mapping_source_status === 'SOURCE_MAPPING_AVAILABLE_UNPARSED' ? 'Pemetaan tersedia di kurikulum — belum berhasil dibaca sistem.' : 'Tidak ada pemetaan resmi pada dokumen kurikulum.'),
            'mapping_source_status'     => $mapping_source_status,
            'effective_mapping_type'    => $effective_mapping_type,
            'mapping_type'              => $effective_mapping_type, // backward compatibility
            'mapping_label'             => $mapping_label,
            'mapped_cpls'               => $mapped_cpls,
            'mapped_cpl'                => $mapped_cpls,
            'mapped_cpl_count'          => count($mapped_cpls),
            'evidence_path'             => $evidence_path,
            'desc_status'               => $desc_source,
            'desc_source_section'       => $desc_source_section,
            'description_source_section'=> $desc_source_section,
            'desc_text'                 => $desc_text,
            'bk_found'                  => $bk_found,
            'bk_text'                   => $bk_text,
            'semester'                  => $meta['semester'],
            'sks_teori'                 => $meta['sks_teori'],
            'sks_praktik'               => $meta['sks_praktik'],
            'sks_total'                 => $meta['sks_total'],
            'can_generate_cpmk'         => $can_generate_cpmk,
            'overall_readiness'         => $overall_readiness
        ];
    }

    /**
     * AJAX: Pengecekan Faktual Curriculum Readiness saat Mata Kuliah dipilih
     */
    public function ajax_check_curriculum_readiness()
    {
        $this->output->set_content_type('application/json');
        $id_ptk  = $this->session->userdata('id_ptk');
        $kode_mk = trim((string)($this->input->post('kode_mk') ?: $this->input->get('kode_mk')));
        $nm_mk   = trim((string)($this->input->post('nm_mk') ?: ($this->input->post('nama_mk') ?: ($this->input->post('mata_kuliah') ?: ''))));
        $prodi   = trim((string)($this->input->post('prodi') ?: ($this->input->post('nama_prodi') ?: '')));
        $id_mk   = trim((string)($this->input->post('id_mk') ?: ''));

        $kur_found       = false;
        $pustaka_info    = null;
        $grounding_info  = null;

        // 1. Ambil Dokumen Kurikulum Faktual (Source of Truth) & Structured Library (Prioritas)
        if (!empty($prodi) || !empty($kode_mk)) {
            $struct_res = $this->_load_structured_curriculum_library($prodi, null, $kode_mk);
            if ($struct_res['status'] && $struct_res['structured_ready'] && !empty($struct_res['payload'])) {
                $kur_found    = true;
                $pustaka_info = $struct_res['pustaka'];
                $grounding_info = $this->_resolve_course_grounding_from_structured_library(
                    $struct_res['payload'],
                    $kode_mk,
                    $nm_mk,
                    $prodi
                );
            } else {
                $kur_res = $this->_get_kurikulum_content($prodi, null, $kode_mk);
                if ($kur_res['found'] && !empty($kur_res['content'])) {
                    $kur_found    = true;
                    $pustaka_info = $kur_res['pustaka'];
                    $content      = $kur_res['content'];

                    // Analisis komprehensif grounding kurikulum (fallback runtime)
                    $grounding_info = $this->_analyze_curriculum_grounding($content, $kode_mk, $nm_mk, $prodi);
                }
            }
        }

        // 2. Cek Database siakad_rps_obe untuk data CPMK existing
        $this->load->model('Rps_obe_model');
        $rps_row = null;
        if (!empty($kode_mk)) {
            $rps_row = $this->db->where('kode_mk', $kode_mk)->where('id_ptk', $id_ptk)->order_by('id_rps', 'DESC')->get('siakad_rps_obe')->row();
        }
        if (!$rps_row && !empty($nm_mk)) {
            $rps_row = $this->db->where('nm_mk', $nm_mk)->where('id_ptk', $id_ptk)->order_by('id_rps', 'DESC')->get('siakad_rps_obe')->row();
        }

        $cpmk_existing_data = [];
        $cpmk_status_val = null;

        if ($rps_row) {
            if (!empty($rps_row->cpmk_json)) {
                $parsed = json_decode($rps_row->cpmk_json, true);
                if (is_array($parsed) && !empty($parsed)) {
                    $cpmk_existing_data = $parsed;
                    $cpmk_status_val    = $rps_row->cpmk_status ?: 'AI_PROPOSAL';
                }
            } elseif (!empty($rps_row->tujuan_belajar)) {
                $cpmk_status_val = $rps_row->cpmk_status; // NULL / Legacy
            }
        }

        $cpmk_count = count($cpmk_existing_data);
        if ($cpmk_status_val === 'APPROVED') {
            $cpmk_status_label = 'APPROVED (' . $cpmk_count . ' CPMK)';
        } elseif ($cpmk_status_val === 'AI_PROPOSAL' || (!empty($cpmk_existing_data) && empty($cpmk_status_val))) {
            $cpmk_status_label = 'Draft AI (' . $cpmk_count . ' CPMK)';
        } elseif (!empty($rps_row->tujuan_belajar)) {
            $cpmk_status_label = 'RPS Legacy (Format Teks)';
        } else {
            $cpmk_status_label = 'Belum Ada';
        }

        // Bentuk checks terstruktur berbasis hasil grounding
        $found_mk               = $grounding_info ? $grounding_info['found_mk'] : false;
        $total_cpl              = $grounding_info ? $grounding_info['cpl_data']['total_unique'] : 0;
        $cpl_items              = $grounding_info ? $grounding_info['cpl_data']['items'] : [];
        $mapping_source_status  = $grounding_info ? $grounding_info['mapping_source_status'] : 'NO_EXPLICIT_SOURCE';
        $effective_mapping_type = $grounding_info ? $grounding_info['effective_mapping_type'] : 'NOT_AVAILABLE';
        $mapping_lbl            = $grounding_info ? $grounding_info['mapping_label'] : '— Tidak ditemukan';
        $mapped_cpls            = $grounding_info ? $grounding_info['mapped_cpls'] : [];
        $bk_found               = $grounding_info ? $grounding_info['bk_found'] : false;
        $bk_text                = $grounding_info ? $grounding_info['bk_text'] : '';
        $desc_status            = $grounding_info ? $grounding_info['desc_status'] : 'NOT_FOUND';
        $desc_text              = $grounding_info ? $grounding_info['desc_text'] : '';
        $prodi_resmi            = $grounding_info ? $grounding_info['prodi_resmi'] : null;

        $has_cpl = ($total_cpl > 0);
        $can_generate_cpmk = ($kur_found && $found_mk && $has_cpl && ($bk_found || $desc_status !== 'NOT_FOUND'));
        $overall_readiness = $can_generate_cpmk ? 'READY' : 'NOT_READY';

        $checks = [
            'kurikulum_dokumen' => [
                'status'           => $kur_found,
                'label'            => $kur_found ? 'Tersedia' : 'Tidak Ditemukan',
                'detail'           => $pustaka_info['judul_dokumen'] ?? ($kur_found ? 'Dokumen kurikulum prodi' : 'Belum diunggah'),
                'nama_prodi_resmi' => $prodi_resmi
            ],
            'mk_terdaftar' => [
                'status' => $found_mk,
                'label'  => $found_mk ? 'Ditemukan' : 'Tidak Ditemukan',
                'detail' => $found_mk ? 'Mata kuliah terdaftar dalam dokumen kurikulum' : 'Tidak ditemukan dalam naskah kurikulum'
            ],
            'cpl_prodi' => [
                'status'             => $has_cpl,
                'total_cpl'          => $total_cpl,
                'official_cpl_count' => $total_cpl,
                'label'              => $has_cpl ? ($total_cpl . ' CPL ditemukan') : 'Tidak Ada',
                'detail'             => $has_cpl ? ('Total ' . $total_cpl . ' butir CPL resmi terdaftar') : 'CPL prodi belum terdata / belum terdefinisi',
                'items'              => $cpl_items
            ],
            'cpl_bk_mapping' => [
                'status'                => ($grounding_info && ($grounding_info['cpl_bk_mapping_status'] ?? '') === 'PARSED'),
                'cpl_bk_mapping_status' => $grounding_info['cpl_bk_mapping_status'] ?? 'NOT_AVAILABLE',
                'cpl_bk_mappable_count' => $grounding_info['cpl_bk_mappable_count'] ?? null,
                'label'                 => ($grounding_info && ($grounding_info['cpl_bk_mapping_status'] ?? '') === 'PARSED' && ($grounding_info['cpl_bk_mappable_count'] ?? null) !== null)
                                            ? ($grounding_info['cpl_bk_mappable_count'] . ' CPL memiliki mapping BK')
                                            : (($grounding_info && ($grounding_info['cpl_bk_mapping_status'] ?? '') === 'AVAILABLE_UNPARSED')
                                                ? 'Tersedia di Kurikulum'
                                                : 'Tidak Ada Matriks CPL ↔ BK'),
                'detail'                => ($grounding_info && ($grounding_info['cpl_bk_mapping_status'] ?? '') === 'PARSED' && ($grounding_info['cpl_bk_mappable_count'] ?? null) !== null)
                                            ? ($grounding_info['cpl_bk_mappable_count'] . ' CPL tercantum pada matriks CPL ↔ BK kurikulum')
                                            : (($grounding_info && ($grounding_info['cpl_bk_mapping_status'] ?? '') === 'AVAILABLE_UNPARSED')
                                                ? 'Matriks CPL ↔ BK tersedia di dokumen kurikulum; pemetaan MK menggunakan direct matrix'
                                                : 'Matriks hubungan CPL dan Bahan Kajian tidak didefinisikan terpisah')
            ],
            'cpl_mk_mapping' => [
                'status'                 => $has_cpl && in_array($effective_mapping_type, ['EXPLICIT_MATRIX', 'EXPLICIT_SECTION', 'DERIVED_VIA_BK', 'AI_EXTRACTED_MAPPING']),
                'mapping_source_status'  => $mapping_source_status,
                'effective_mapping_type' => $effective_mapping_type,
                'mapping_type'           => $effective_mapping_type, // backward compatibility
                'mapped_cpl_count'       => count($mapped_cpls),
                'label'                  => !empty($mapped_cpls) ? (count($mapped_cpls) . ' CPL terpetakan untuk MK terpilih') : $mapping_lbl,
                'detail'                 => !$has_cpl ? 'CPL resmi belum terdaftar di kurikulum' : (!empty($mapped_cpls) ? implode(', ', $mapped_cpls) : 'Pemetaan CPL-MK ' . $effective_mapping_type),
                'mapped_cpls'            => $mapped_cpls
            ],
            'bahan_kajian' => [
                'status'             => $bk_found,
                'bahan_kajian_count' => $grounding_info['bahan_kajian_count'] ?? 0,
                'relevant_bk_count'  => $grounding_info['relevant_bk_count'] ?? 0,
                'label'              => ($grounding_info && $grounding_info['bahan_kajian_count'] > 0) ? ($grounding_info['bahan_kajian_count'] . ' BK kurikulum' . ($grounding_info['relevant_bk_count'] > 0 ? (' / ' . $grounding_info['relevant_bk_count'] . ' BK terkait MK') : '')) : ($bk_found ? 'Ditemukan' : 'Tidak Ditemukan'),
                'detail'             => $bk_text ?: ($bk_found ? 'Bahan kajian terdefinisi di kurikulum' : 'Tidak ada bahan kajian eksplisit')
            ],
            'deskripsi_mk' => [
                'status' => ($desc_status === 'AVAILABLE_FROM_CURRICULUM'),
                'label'  => ($desc_status === 'AVAILABLE_FROM_CURRICULUM') ? 'Tersedia dari Kurikulum' : (($desc_status === 'AVAILABLE_FROM_RPS') ? 'Tersedia dari RPS' : 'Tidak Ditemukan'),
                'detail' => $desc_text ?: (($desc_status !== 'NOT_FOUND') ? 'Deskripsi tersedia' : 'Belum ada deskripsi')
            ],
            'cpmk_status' => [
                'status' => $cpmk_status_val,
                'label'  => $cpmk_status_label,
                'detail' => $cpmk_status_label
            ]
        ];

        $cpl_mk_saved_data   = [];
        $cpl_mk_status_val   = null;
        $deskripsi_mk_val    = '';
        $deskripsi_mk_source = 'CURRICULUM';
        $referensi_val       = '';

        if ($rps_row) {
            if (!empty($rps_row->cpl_mk_json)) {
                $parsed_cpl_mk = json_decode($rps_row->cpl_mk_json, true);
                if (is_array($parsed_cpl_mk)) {
                    if (isset($parsed_cpl_mk['items']) && is_array($parsed_cpl_mk['items'])) {
                        $cpl_mk_saved_data = $parsed_cpl_mk['items'];
                    } else {
                        $cpl_mk_saved_data = $parsed_cpl_mk;
                    }
                }
            }
            $cpl_mk_status_val   = $rps_row->cpl_mk_status ?: null;
            $deskripsi_mk_val    = $rps_row->deskripsi_mata_kuliah ?: ($desc_text ?: '');
            $deskripsi_mk_source = $rps_row->deskripsi_mk_source ?: ($desc_status === 'AVAILABLE_FROM_CURRICULUM' ? 'CURRICULUM' : 'MANUAL');
            $referensi_val       = $rps_row->referensi ?: '';
        } else {
            $deskripsi_mk_val    = $desc_text ?: '';
            $deskripsi_mk_source = $desc_status === 'AVAILABLE_FROM_CURRICULUM' ? 'CURRICULUM' : 'MANUAL';
        }

        echo json_encode([
            'status'                => true,
            'overall_readiness'     => $overall_readiness,
            'can_generate_cpmk'     => $can_generate_cpmk,
            'checks'                => $checks,
            'cpl_prodi'             => $cpl_items,
            'official_cpl_count'    => $total_cpl,
            'cpl_bk_mapping_status' => $grounding_info['cpl_bk_mapping_status'] ?? 'NOT_AVAILABLE',
            'cpl_bk_mappable_count' => $grounding_info['cpl_bk_mappable_count'] ?? null,
            'mapped_cpl_count'      => count($mapped_cpls),
            'cpl_mk_data'           => $cpl_mk_saved_data,
            'cpl_mk_status'         => $cpl_mk_status_val,
            'deskripsi_mk'          => $deskripsi_mk_val,
            'deskripsi_mk_source'   => $deskripsi_mk_source,
            'referensi'             => $referensi_val,
            'cpmk_data'             => $cpmk_existing_data,
            'cpmk_status'           => $cpmk_status_val,
            'id_rps'                => $rps_row ? (int)$rps_row->id_rps : null,
            'semester'              => $grounding_info['semester'] ?? null,
            'sks_teori'             => $grounding_info['sks_teori'] ?? null,
            'sks_praktik'           => $grounding_info['sks_praktik'] ?? null,
            'sks_total'             => $grounding_info['sks_total'] ?? null,
            'bahan_kajian_count'    => $grounding_info['bahan_kajian_count'] ?? 0,
            'relevant_bk_count'     => $grounding_info['relevant_bk_count'] ?? 0,
            'bahan_kajian'          => $grounding_info['bahan_kajian'] ?? [],
            'mapping_evidence'      => $grounding_info['evidence_path'] ?? ''
        ]);
    }

    /**
     * AJAX: Load data lengkap Studio CPL & Deskripsi MK
     */
    public function ajax_get_cpl_studio()
    {
        $this->output->set_content_type('application/json');
        $id_ptk  = $this->session->userdata('id_ptk');
        $id_rps  = (int)($this->input->post('id_rps') ?: $this->input->get('id_rps'));
        $kode_mk = trim((string)($this->input->post('kode_mk') ?: $this->input->get('kode_mk')));
        $nm_mk   = trim((string)($this->input->post('nm_mk') ?: ($this->input->post('nama_mk') ?: '')));
        $prodi   = trim((string)($this->input->post('prodi') ?: ($this->input->post('nama_prodi') ?: '')));

        // 2. Ambil data tersimpan dari DB siakad_rps_obe
        $this->load->model('Rps_obe_model');
        $rps_row = null;
        if (!empty($id_rps)) {
            $rps_row = $this->db->where('id_rps', $id_rps)->get('siakad_rps_obe')->row();
        }
        if (!$rps_row && !empty($kode_mk)) {
            if (!empty($id_ptk)) {
                $rps_row = $this->db->where('kode_mk', $kode_mk)->where('id_ptk', $id_ptk)->order_by('id_rps', 'DESC')->get('siakad_rps_obe')->row();
            }
            if (!$rps_row) {
                $rps_row = $this->db->where('kode_mk', $kode_mk)->order_by('id_rps', 'DESC')->get('siakad_rps_obe')->row();
            }
        }
        if (!$rps_row && !empty($nm_mk)) {
            if (!empty($id_ptk)) {
                $rps_row = $this->db->where('nm_mk', $nm_mk)->where('id_ptk', $id_ptk)->order_by('id_rps', 'DESC')->get('siakad_rps_obe')->row();
            }
            if (!$rps_row) {
                $rps_row = $this->db->where('nm_mk', $nm_mk)->order_by('id_rps', 'DESC')->get('siakad_rps_obe')->row();
            }
        }

        if (empty($prodi) && $rps_row) {
            $prodi = $this->_resolve_prodi_for_rps($rps_row);
        }

        // 1. Ambil Dokumen Kurikulum via Structured Library (prioritas) atau Runtime Parser (fallback)
        $grounding_info = null;
        $struct_res = $this->_load_structured_curriculum_library($prodi, null, $kode_mk);
        if ($struct_res['status'] && $struct_res['structured_ready'] && !empty($struct_res['payload'])) {
            $grounding_info = $this->_resolve_course_grounding_from_structured_library(
                $struct_res['payload'],
                $kode_mk,
                $nm_mk,
                $prodi,
                $rps_row
            );
        } else {
            $kur_res = $this->_get_kurikulum_content($prodi, null, $kode_mk);
            $content = $kur_res['found'] ? $kur_res['content'] : '';
            $grounding_info = !empty($content) ? $this->_analyze_curriculum_grounding($content, $kode_mk, $nm_mk, $prodi) : null;
        }

        $cpl_data = $grounding_info ? $grounding_info['cpl_data'] : ['items' => [], 'allowed_lookup' => []];
        $official_items = $cpl_data['items'] ?? [];
        $mapped_cpls    = $grounding_info['mapped_cpls'] ?? [];
        $effective_mapping_type = $grounding_info['effective_mapping_type'] ?? 'NOT_AVAILABLE';
        $mapping_source_status  = $grounding_info['mapping_source_status'] ?? 'NO_EXPLICIT_SOURCE';
        $cpl_bk_pairs = $grounding_info['cpl_bk_pairs'] ?? [];
        $all_bks = $grounding_info['bahan_kajian'] ?? [];
        $target_bk_codes = $grounding_info['target_bk_codes'] ?? [];

        $cpl_mk_saved_list = [];
        $cpl_mk_status = null;
        $deskripsi_mk = '';
        $deskripsi_source = 'CURRICULUM';
        $referensi = '';

        if ($rps_row) {
            if (!empty($rps_row->cpl_mk_json)) {
                $parsed = json_decode($rps_row->cpl_mk_json, true);
                if (is_array($parsed)) {
                    if (isset($parsed['items']) && is_array($parsed['items'])) {
                        $cpl_mk_saved_list = $parsed['items'];
                    } else {
                        $cpl_mk_saved_list = $parsed;
                    }
                }
            }
            $cpl_mk_status = $rps_row->cpl_mk_status ?: null;
            if (!empty($rps_row->deskripsi_mata_kuliah)) {
                $deskripsi_mk = $rps_row->deskripsi_mata_kuliah;
            }
            if (!empty($rps_row->deskripsi_mk_source)) {
                $deskripsi_source = $rps_row->deskripsi_mk_source;
            }
            if (!empty($rps_row->referensi)) {
                $referensi = $rps_row->referensi;
            }
        }

        // Cek apakah kurikulum prodi berstatus STALE
        $is_stale_curriculum = false;
        $stale_warning = '';
        if ($struct_res['status'] && !empty($struct_res['pustaka'])) {
            $pustaka_status = $struct_res['pustaka']['normalization_status'] ?? '';
            if ($pustaka_status === 'STALE') {
                $is_stale_curriculum = true;
                $stale_warning = 'Dokumen kurikulum prodi telah diperbarui sejak RPS ini dibuat. Silakan tinjau kembali pilihan CPL.';
            }
        }

        // Jika belum ada deskripsi tersimpan di siakad_rps_obe:
        // Prioritas Default Faktual: Dari dokumen kurikulum prodi (grounding)
        // RPS Lama TIDAK di-auto-populate tanpa aksi eksplisit tombol "Ambil dari RPS Lama" dari user
        if (empty($deskripsi_mk)) {
            if (!empty($grounding_info['desc_text']) && ($grounding_info['desc_status'] === 'AVAILABLE_FROM_CURRICULUM')) {
                $deskripsi_mk = $grounding_info['desc_text'];
                $deskripsi_source = 'CURRICULUM';
            } else {
                $deskripsi_mk = '';
                $deskripsi_source = 'MANUAL';
            }
        }

        // 3. Jika belum pernah disimpan, bentuk kandidat awal dari mapping kurikulum
        $selected_map = [];
        if (!empty($cpl_mk_saved_list)) {
            $is_draft = ($cpl_mk_status === 'DRAFT' || empty($cpl_mk_status));
            $all_saved_roles_primary = true;
            $saved_count = count($cpl_mk_saved_list);
            foreach ($cpl_mk_saved_list as $item) {
                $r = strtoupper(trim($item['role'] ?? ''));
                if ($r !== 'PRIMARY') {
                    $all_saved_roles_primary = false;
                    break;
                }
            }

            // Untuk record DRAFT: deteksi status auto-initialization (semua diset PRIMARY) dan reset role ke UNCLASSIFIED
            // Untuk record APPROVED: JANGAN diubah/dimigrasi diam-diam, pertahankan role hasil review dosen
            $reset_to_unclassified = ($is_draft && $all_saved_roles_primary && $saved_count > 0);

            foreach ($cpl_mk_saved_list as $item) {
                $item_code = strtoupper(preg_replace('/\s+/', '-', trim($item['code'] ?? ($item['kode'] ?? ($item['cpl_code'] ?? '')))));
                if (!empty($item_code)) {
                    $is_included = isset($item['included']) ? (bool)$item['included'] : true;
                    $raw_role = strtoupper(trim($item['role'] ?? ''));
                    
                    if ($is_included) {
                        if ($reset_to_unclassified) {
                            $assigned_role = 'UNCLASSIFIED';
                            $assigned_sel_status = 'UNCLASSIFIED';
                        } else {
                            $assigned_role = ($raw_role === 'PRIMARY') ? 'PRIMARY' : (($raw_role === 'SUPPORTING') ? 'SUPPORTING' : 'UNCLASSIFIED');
                            $assigned_sel_status = ($assigned_role === 'PRIMARY') ? 'SELECTED_PRIMARY' : (($assigned_role === 'SUPPORTING') ? 'SELECTED_SUPPORTING' : 'UNCLASSIFIED');
                        }
                    } else {
                        $assigned_role = null;
                        $assigned_sel_status = 'NOT_SELECTED_FOR_RPS';
                    }

                    $is_official_mapped = in_array($item_code, $mapped_cpls) || !empty($item['official_mapped']) || !empty($item['is_mapped']);
                    $item_prov = trim($item['provenance'] ?? ($cpl_mk_status === 'APPROVED' ? 'APPROVED' : ($is_official_mapped ? 'FACTUAL' : 'MANUAL')));

                    $selected_map[$item_code] = [
                        'role'             => $assigned_role,
                        'source'           => trim($item['source'] ?? ($item['source_type'] ?? ($item['provenance'] ?? 'MANUAL'))),
                        'provenance'       => $item_prov,
                        'included'         => $is_included,
                        'selection_status' => $assigned_sel_status,
                        'official_mapped'  => $is_official_mapped,
                        'approved'         => !empty($item['approved']) || ($cpl_mk_status === 'APPROVED')
                    ];
                }
            }
        } elseif (!empty($mapped_cpls)) {
            foreach ($mapped_cpls as $c_code) {
                $norm_code = strtoupper(preg_replace('/\s+/', '-', trim($c_code)));
                if (!empty($norm_code)) {
                    $selected_map[$norm_code] = [
                        'role'             => 'UNCLASSIFIED',
                        'source'           => $effective_mapping_type,
                        'provenance'       => 'FACTUAL',
                        'included'         => true,
                        'selection_status' => 'UNCLASSIFIED',
                        'official_mapped'  => true,
                        'approved'         => false
                    ];
                }
            }
        }

        // Helper untuk pencocokan kode CPL toleran alias (misal KK- vs KS-)
        $check_cpl_entry = function($code_to_check, $map_or_array, $is_array = false) {
            $code_clean = strtoupper(preg_replace('/\s+/', '-', trim($code_to_check)));
            $candidates = [$code_clean];
            if (str_starts_with($code_clean, 'KK-')) {
                $candidates[] = str_replace('KK-', 'KS-', $code_clean);
                $candidates[] = str_replace('KK-', 'KK', $code_clean);
                $candidates[] = str_replace('KK-', 'KS', $code_clean);
            } elseif (str_starts_with($code_clean, 'KS-')) {
                $candidates[] = str_replace('KS-', 'KK-', $code_clean);
                $candidates[] = str_replace('KS-', 'KK', $code_clean);
                $candidates[] = str_replace('KS-', 'KS', $code_clean);
            }
            foreach ($candidates as $cand) {
                if ($is_array) {
                    if (in_array($cand, $map_or_array)) return true;
                } else {
                    if (isset($map_or_array[$cand])) return $map_or_array[$cand];
                }
            }
            return $is_array ? false : null;
        };

        // Siapkan list komprehensif seluruh CPL prodi beserta supporting BK context
        $cpl_full_list = [];
        foreach ($official_items as $cpl) {
            $code = strtoupper(preg_replace('/\s+/', '-', trim($cpl['code'] ?? ($cpl['kode'] ?? ''))));
            $matched_selected = $check_cpl_entry($code, $selected_map, false);
            $isSelected = ($matched_selected !== null);
            $isMapped = $check_cpl_entry($code, $mapped_cpls, true);

            if ($isMapped) {
                if ($effective_mapping_type === 'DERIVED_VIA_BK') {
                    $mapping_badge = 'Terpetakan via BK';
                } elseif ($effective_mapping_type === 'EXPLICIT_MATRIX' || $effective_mapping_type === 'EXPLICIT_SECTION') {
                    $mapping_badge = 'Terpetakan Langsung';
                } else {
                    $mapping_badge = 'Terpetakan';
                }
            } else {
                if ($mapping_source_status === 'SOURCE_MAPPING_AVAILABLE_UNPARSED' || $mapping_source_status === 'SOURCE_MAPPING_PARTIAL') {
                    $mapping_badge = 'CPL Resmi (Pemetaan Kurikulum Belum Terbaca)';
                } elseif ($mapping_source_status === 'SOURCE_MAPPING_NOT_AVAILABLE') {
                    $mapping_badge = 'CPL Resmi (Tidak Ada Pemetaan Resmi)';
                } elseif ($effective_mapping_type === 'IN_MATRIX_NO_CPL_MARKED') {
                    $mapping_badge = 'CPL Resmi (MK Tidak Diberi CPL di Matriks)';
                } elseif ($effective_mapping_type === 'ACTIVE_COURSE_OUTSIDE_CPL_MATRIX') {
                    $mapping_badge = 'CPL Resmi (MK di Luar Matriks CPL-MK)';
                } elseif ($effective_mapping_type === 'COVERED_BY_AGGREGATE_MATRIX_TRACK') {
                    $mapping_badge = 'CPL Resmi (Track Magang Agregat)';
                } else {
                    $mapping_badge = 'CPL Resmi';
                }
            }

            // Temukan Bahan Kajian (BK) pendukung untuk butir CPL ini
            $linked_bks = [];
            foreach ($cpl_bk_pairs as $pair) {
                if ($pair['cpl_code'] === $code || $check_cpl_entry($pair['cpl_code'], [$code => true])) {
                    $bk_code = $pair['bk_code'];
                    $bk_name = '';
                    foreach ($all_bks as $b) {
                        if ($b['code'] === $bk_code) {
                            $bk_name = $b['name'];
                            break;
                        }
                    }
                    $is_course_bk = in_array($bk_code, $target_bk_codes);
                    $linked_bks[] = [
                        'code'         => $bk_code,
                        'name'         => $bk_name,
                        'is_course_bk' => $is_course_bk
                    ];
                }
            }

            if ($isSelected) {
                $item_included = (bool)($matched_selected['included'] ?? true);
                $item_role = $item_included ? ($matched_selected['role'] ?? 'UNCLASSIFIED') : null;
                $item_sel_status = $matched_selected['selection_status'] ?? ($item_included ? ($item_role ?: 'UNCLASSIFIED') : 'NOT_SELECTED_FOR_RPS');
                $item_provenance = $matched_selected['provenance'] ?? ($isMapped ? 'FACTUAL' : 'MANUAL');
                $item_source = $matched_selected['source'] ?? ($isMapped ? $effective_mapping_type : 'MANUAL');
            } else {
                $item_included = false;
                $item_role = null;
                $item_sel_status = $isMapped ? 'NOT_SELECTED_FOR_RPS' : 'UNSELECTED';
                $item_provenance = $isMapped ? 'FACTUAL' : 'MANUAL';
                $item_source = $isMapped ? $effective_mapping_type : 'MANUAL';
            }

            $cpl_full_list[] = [
                'code'               => $code,
                'kode'               => $code,
                'source_code'        => $cpl['source_code'] ?? ($code . '.'),
                'category'           => $cpl['category'] ?? ($cpl['kategori'] ?? 'CPL'),
                'description'        => $cpl['description'] ?? ($cpl['deskripsi'] ?? ($cpl['teks'] ?? '')),
                'source_section'     => $cpl['source_section'] ?? 'CURRICULUM_CPL',
                'is_official'        => isset($cpl['is_official']) ? (bool)$cpl['is_official'] : true,
                'is_normalized_code' => !empty($cpl['is_normalized_code']),
                'selected'           => $item_included,
                'included'           => $item_included,
                'is_mapped'          => $isMapped,
                'official_mapped'    => $isMapped,
                'mapping_badge'      => $mapping_badge,
                'role'               => $item_role,
                'selection_status'   => $item_sel_status,
                'source'             => $item_source,
                'provenance'         => $item_provenance,
                'approved'           => $isSelected ? ($cpl_mk_status === 'APPROVED') : false,
                'linked_bks'         => $linked_bks
            ];
        }

        $clean_deskripsi_out = $this->_clean_deskripsi_text($deskripsi_mk);
        $clean_referensi_out = $this->_clean_referensi_text($referensi);

        echo json_encode([
            'status'                 => true,
            'id_rps'                 => $rps_row ? (int)$rps_row->id_rps : null,
            'cpl_mk_status'          => $cpl_mk_status,
            'is_stale_curriculum'    => $is_stale_curriculum,
            'stale_warning'          => $stale_warning,
            'cpl_list'               => $cpl_full_list,
            'total_cpl'              => count($official_items),
            'official_cpl_count'     => count($official_items),
            'cpl_bk_mapping_status'  => $grounding_info['cpl_bk_mapping_status'] ?? 'NOT_AVAILABLE',
            'cpl_bk_mappable_count'  => $grounding_info['cpl_bk_mappable_count'] ?? null,
            'mapped_cpls'            => $mapped_cpls,
            'mapped_cpl_count'       => count($mapped_cpls),
            'effective_mapping_type' => $effective_mapping_type,
            'mapping_source_status'  => $mapping_source_status,
            'mapping_label'          => $grounding_info['mapping_label'] ?? '',
            'mapping_source_exists'  => $grounding_info['mapping_source_exists'] ?? false,
            'mapping_source_section' => $grounding_info['mapping_source_section'] ?? null,
            'mapping_parse_status'   => $grounding_info['mapping_parse_status'] ?? $mapping_source_status,
            'mapping_parse_message'  => $grounding_info['mapping_parse_message'] ?? '',
            'mapping_audit'          => [
                'mapping_source_exists'  => $grounding_info['mapping_source_exists'] ?? false,
                'mapping_source_section' => $grounding_info['mapping_source_section'] ?? null,
                'mapping_parse_status'   => $grounding_info['mapping_parse_status'] ?? $mapping_source_status,
                'mapping_parse_message'  => $grounding_info['mapping_parse_message'] ?? ''
            ],
            'curriculum_desc'        => $this->_clean_deskripsi_text($grounding_info['desc_text'] ?? ''),
            'deskripsi_mata_kuliah'  => $clean_deskripsi_out,
            'deskripsi_mk'           => $clean_deskripsi_out,
            'deskripsi_mk_source'    => $deskripsi_source,
            'referensi'              => $clean_referensi_out,
            'bahan_kajian'           => $grounding_info['bk_text'] ?? '',
            'bahan_kajian_count'     => $grounding_info['bahan_kajian_count'] ?? 0,
            'relevant_bk_count'      => $grounding_info['relevant_bk_count'] ?? 0,
            'aggregate_domains'      => $grounding_info['aggregate_domains'] ?? []
        ]);
    }

    /**
     * AJAX: Minta Rekomendasi CPL dari AI (HANYA dari official CPL codes)
     */
    public function ajax_generate_cpl_recommendation()
    {
        $this->output->set_content_type('application/json');
        $id_ptk = $this->session->userdata('id_ptk');

        $kode_mk     = trim((string)$this->input->post('kode_mk'));
        $mata_kuliah = trim((string)($this->input->post('mata_kuliah') ?: $this->input->post('nm_mk')));
        $prodi       = trim((string)($this->input->post('prodi') ?: $this->input->post('nama_prodi')));
        $sks         = (int)($this->input->post('sks') ?: 3);
        $semester    = trim((string)$this->input->post('semester'));
        $deskripsi   = trim((string)$this->input->post('deskripsi_mk'));
        $bahan_kajian = trim((string)$this->input->post('bahan_kajian'));

        // 1. Ambil official CPL prodi & pemetaan langsung faktual via Structured Library
        $grounding_info = null;
        $struct_res = $this->_load_structured_curriculum_library($prodi, null, $kode_mk);
        if ($struct_res['status'] && $struct_res['structured_ready'] && !empty($struct_res['payload'])) {
            $grounding_info = $this->_resolve_course_grounding_from_structured_library(
                $struct_res['payload'],
                $kode_mk,
                $mata_kuliah,
                $prodi,
                null
            );
        } else {
            $kur_res = $this->_get_kurikulum_content($prodi, null, $kode_mk);
            $content = $kur_res['found'] ? $kur_res['content'] : '';
            $grounding_info = !empty($content) ? $this->_analyze_curriculum_grounding($content, $kode_mk, $mata_kuliah, $prodi) : null;
        }

        $cpl_data = $grounding_info ? $grounding_info['cpl_data'] : ['items' => [], 'allowed_lookup' => []];
        $official_items = $cpl_data['items'] ?? [];
        $allowed_lookup = $cpl_data['allowed_lookup'] ?? [];
        $mapped_cpls    = $grounding_info['mapped_cpls'] ?? [];

        if (empty($official_items)) {
            echo json_encode(['status' => false, 'msg' => 'CPL resmi prodi belum tersedia pada dokumen kurikulum.']);
            return;
        }

        // 2. Siapkan prompt ke AI
        $api_setting = $this->Setting_api_key_model->get_api_key($id_ptk);
        $provider = $api_setting->ai_provider ?? 'gemini';
        $api_key  = $api_setting->api_key ?? '';
        $model    = $api_setting->ai_model ?? null;

        if (empty($api_key)) {
            echo json_encode(['status' => false, 'msg' => 'Kunci API AI belum dikonfigurasi pada akun Anda.']);
            return;
        }

        $cpl_list_text = "";
        foreach ($official_items as $ci) {
            $cpl_list_text .= "- [{$ci['code']}] ({$ci['category']}): {$ci['description']}\n";
        }

        $mapped_text = "";
        if (!empty($mapped_cpls)) {
            $mapped_text = "CPL TERPETAKAN LANGSUNG DARI KURIKULUM (WAJIB DIPERTAHANKAN):\n"
                . "Mata kuliah ini memiliki pemetaan kurikulum resmi pada butir CPL berikut: " . implode(', ', $mapped_cpls) . "\n"
                . "Instruksi: Seluruh CPL terpetakan ini WAJIB dimasukkan dalam daftar rekomendasi output Anda dan tentukan perannya (PRIMARY / SUPPORTING).\n\n";
        }

        $system_prompt = "Anda adalah Pakar Kurikulum OBE Pendidikan Tinggi Indonesia.\n"
            . "Tugas Anda adalah merekomendasikan dan mengklasifikasikan peran butir CPL resmi untuk mata kuliah berikut.\n\n"
            . "ATURAN MUTLAK:\n"
            . "1. HANYA PILIH DARI DAFTAR OFFICIAL CPL RESMI YANG DIBERIKAN DI BAWAH INI. DILARANG KERAS MENCIPTAKAN ATAU MENGARANG KODE CPL BARU!\n"
            . "2. CPL yang sudah terpetakan langsung pada kurikulum resmi WAJIB dipertahankan dan disertakan dalam rekomendasi.\n"
            . "3. Bagilah ke dalam dua peran:\n"
            . "   - PRIMARY: CPL substantif utama yang secara langsung diukur dan menjadi target esensial mata kuliah ini (1-3 butir).\n"
            . "   - SUPPORTING: CPL pendukung seperti sikap, etika, atau keterampilan umum (1-3 butir).\n"
            . "4. Format output WAJIB HANYA JSON murni berikut:\n\n"
            . "```json\n"
            . "{\n"
            . '  "recommendations": [' . "\n"
            . "    {\n"
            . '      "code": "P-9",' . "\n"
            . '      "role": "PRIMARY",' . "\n"
            . '      "reason": "Alasan singkat keselarasan materi dengan CPL ini..."' . "\n"
            . "    }\n"
            . "  ]\n"
            . "}\n"
            . "```\n";

        $user_prompt = "Mata Kuliah: {$mata_kuliah} (" . ($kode_mk ? "Kode: {$kode_mk}, " : "") . "{$sks} SKS, Semester {$semester})\n"
            . "Program Studi: {$prodi}\n"
            . (!empty($deskripsi) ? "Deskripsi Mata Kuliah: {$deskripsi}\n" : "")
            . (!empty($bahan_kajian) ? "Bahan Kajian: {$bahan_kajian}\n\n" : "\n")
            . $mapped_text
            . "DAFTAR OFFICIAL CPL PRODI YANG TERSEDIA:\n"
            . $cpl_list_text;

        $ai_res = $this->ai_reviewer->generate_review($provider, $api_key, $system_prompt, $user_prompt, false, true, $model);
        if (!$ai_res['status']) {
            echo json_encode(['status' => false, 'msg' => $ai_res['msg']]);
            return;
        }

        $raw_json = $ai_res['review'];
        // Parse JSON
        if (preg_match('/```(?:json)?\s*([\s\S]*?)\s*```/i', $raw_json, $jm)) {
            $raw_json = trim($jm[1]);
        }
        $parsed = json_decode($raw_json, true);
        $recs = $parsed['recommendations'] ?? ($parsed['cpl'] ?? (is_array($parsed) && isset($parsed[0]) ? $parsed : []));

        $valid_recommendations = [];
        $rec_code_map = [];
        $has_primary = false;
        foreach ($recs as $r) {
            $code = strtoupper(preg_replace('/\s+/', '-', trim($r['code'] ?? '')));
            if (isset($allowed_lookup[$code]) || isset($allowed_lookup[str_replace('KS-', 'KK-', $code)]) || isset($allowed_lookup[str_replace('KK-', 'KS-', $code)])) {
                $canonical_code = isset($allowed_lookup[$code]) ? $code : (isset($allowed_lookup[str_replace('KK-', 'KS-', $code)]) ? str_replace('KK-', 'KS-', $code) : (isset($allowed_lookup[str_replace('KS-', 'KK-', $code)]) ? str_replace('KS-', 'KK-', $code) : $code));
                $role = (strtoupper(trim($r['role'] ?? '')) === 'PRIMARY') ? 'PRIMARY' : 'SUPPORTING';
                if ($role === 'PRIMARY') $has_primary = true;
                $valid_recommendations[] = [
                    'code'   => $canonical_code,
                    'role'   => $role,
                    'reason' => trim($r['reason'] ?? 'Rekomendasi keselarasan materi mata kuliah.')
                ];
                $rec_code_map[$canonical_code] = true;
            }
        }

        // Pastikan seluruh CPL Faktual Kurikulum tetap ada dan tidak tertinggal
        if (!empty($mapped_cpls)) {
            foreach ($mapped_cpls as $mc) {
                $norm_mc = strtoupper(preg_replace('/\s+/', '-', trim($mc)));
                $canonical_mc = isset($allowed_lookup[$norm_mc]) ? $norm_mc : (isset($allowed_lookup[str_replace('KK-', 'KS-', $norm_mc)]) ? str_replace('KK-', 'KS-', $norm_mc) : (isset($allowed_lookup[str_replace('KS-', 'KK-', $norm_mc)]) ? str_replace('KS-', 'KK-', $norm_mc) : $norm_mc));
                if (!isset($rec_code_map[$canonical_mc]) && (isset($allowed_lookup[$canonical_mc]) || isset($allowed_lookup[$norm_mc]))) {
                    $valid_recommendations[] = [
                        'code'   => $canonical_mc,
                        'role'   => 'PRIMARY',
                        'reason' => 'Pemetaan faktual kurikulum resmi program studi.'
                    ];
                    $rec_code_map[$canonical_mc] = true;
                    $has_primary = true;
                }
            }
        }

        // Pastikan ada setidaknya 1 PRIMARY jika valid_recommendations ada
        if (!empty($valid_recommendations) && !$has_primary) {
            $valid_recommendations[0]['role'] = 'PRIMARY';
        }

        echo json_encode([
            'status'          => true,
            'mapped_cpls'     => $mapped_cpls,
            'recommendations' => $valid_recommendations
        ]);
    }

    /**
     * AJAX: Cari seluruh arsip RPS lama di database siakad_rps_online yang cocok dengan Kode MK / Nama MK / Kata Kunci
     */
    public function ajax_search_rps_lama_modal()
    {
        $this->output->set_content_type('application/json');
        $kode_mk = trim((string)($this->input->post('kode_mk') ?: $this->input->get('kode_mk')));
        $nm_mk   = trim((string)($this->input->post('nm_mk') ?: ($this->input->post('nama_mk') ?: $this->input->get('nama_mk'))));
        $keyword = trim((string)($this->input->post('keyword') ?: ($this->input->post('q') ?: $this->input->get('q'))));

        $sql = "
            SELECT 
                o.id_rps,
                o.general_mk,
                COALESCE(mk.kode_mk, '') as kode_mk,
                COALESCE(mk.nm_mk, o.general_mk) as nm_mk,
                o.tanggal_rps,
                o.kode_revisi,
                o.dosen_pengampu,
                o.create_by,
                o.create_date,
                COALESCE(
                    NULLIF(TRIM(o.dosen_pengampu), ''),
                    NULLIF(TRIM(CONCAT(COALESCE(u.first_name, ''), ' ', COALESCE(u.last_name, ''))), ''),
                    d.nm_sdm,
                    d_koord.nm_sdm,
                    o.create_by,
                    'Dosen Pengampu'
                ) as nama_penyusun,
                COALESCE(
                    smt_p.nm_smt,
                    smt_kk.nm_smt,
                    CONCAT('TA ', YEAR(o.tanggal_rps), '/', YEAR(o.tanggal_rps)+1),
                    CONCAT('TA ', YEAR(o.create_date), '/', YEAR(o.create_date)+1),
                    'Tahun Tidak Tercatat'
                ) as tahun_ajaran,
                o.deskripsi_mata_kuliah,
                o.referensi
            FROM siakad_rps_online o
            LEFT JOIN siakad_rps_mk_prodi p ON p.id_rps = o.id_rps
            LEFT JOIN feeder_mata_kuliah mk ON mk.id_mk = p.id_mk
            LEFT JOIN users u ON u.id_ptk = o.id_ptk
            LEFT JOIN feeder_dosen d ON d.id_sdm = o.id_ptk
            LEFT JOIN feeder_dosen d_koord ON d_koord.id_sdm = o.koordinator_rps
            LEFT JOIN semester smt_p ON smt_p.id_smt = p.id_smt
            LEFT JOIN feeder_kelas_kuliah kk ON kk.id_kls = p.id_kls
            LEFT JOIN semester smt_kk ON smt_kk.id_smt = kk.id_smt
            WHERE (
                (? != '' AND (
                    mk.kode_mk LIKE CONCAT('%', ?, '%')
                    OR mk.nm_mk LIKE CONCAT('%', ?, '%')
                    OR o.general_mk LIKE CONCAT('%', ?, '%')
                    OR o.dosen_pengampu LIKE CONCAT('%', ?, '%')
                    OR o.deskripsi_mata_kuliah LIKE CONCAT('%', ?, '%')
                ))
                OR (? = '' AND (
                    (? != '' AND mk.kode_mk = ?)
                    OR (? != '' AND LOWER(TRIM(mk.nm_mk)) = LOWER(TRIM(?)))
                    OR (? != '' AND LOWER(TRIM(o.general_mk)) = LOWER(TRIM(?)))
                    OR (? != '' AND LOWER(TRIM(o.general_mk)) LIKE LOWER(CONCAT('%', TRIM(?), '%')))
                ))
            )
            AND o.deskripsi_mata_kuliah IS NOT NULL AND TRIM(o.deskripsi_mata_kuliah) != ''
            GROUP BY o.id_rps
            ORDER BY o.id_rps DESC
            LIMIT 30
        ";

        $rows = $this->db->query($sql, [
            $keyword, $keyword, $keyword, $keyword, $keyword, $keyword,
            $keyword,
            $kode_mk, $kode_mk,
            $nm_mk, $nm_mk,
            $nm_mk, $nm_mk,
            $nm_mk, $nm_mk
        ])->result_array();

        $candidates = [];
        foreach ($rows as $r) {
            $candidates[] = [
                'id_rps'       => (int)$r['id_rps'],
                'general_mk'   => $r['general_mk'],
                'kode_mk'      => $r['kode_mk'],
                'nm_mk'        => $r['nm_mk'],
                'penyusun'     => $this->_clean_html_to_plain_text($r['nama_penyusun']),
                'tahun_ajaran' => $r['tahun_ajaran'],
                'tanggal_rps'  => $r['tanggal_rps'],
                'kode_revisi'  => $r['kode_revisi'],
                'deskripsi_mk' => $this->_clean_deskripsi_text($r['deskripsi_mata_kuliah']),
                'referensi'    => $this->_clean_referensi_text($r['referensi'])
            ];
        }

        echo json_encode([
            'status'     => true,
            'total'      => count($candidates),
            'candidates' => $candidates,
            'query'      => [
                'kode_mk' => $kode_mk,
                'nm_mk'   => $nm_mk,
                'keyword' => $keyword
            ]
        ]);
    }

    /**
     * AJAX: Ambil deskripsi & referensi mata kuliah dari siakad_rps_online (RPS Lama)
     */
    public function ajax_get_deskripsi_rps_lama()
    {
        $this->output->set_content_type('application/json');
        $kode_mk = trim((string)$this->input->post('kode_mk'));
        $nm_mk   = trim((string)($this->input->post('nm_mk') ?: $this->input->post('nama_mk')));

        $res = $this->_find_deskripsi_from_rps_online($kode_mk, $nm_mk);
        if ($res['found']) {
            echo json_encode([
                'status'       => true,
                'deskripsi_mk' => $res['deskripsi_mk'],
